-- ============================================================================
-- SOURCE: 20260920220000_tahfizh_v16_santri_self_guardian_link.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V16 — Perbaikan akar masalah: akun santri tidak pernah tertaut
-- sebagai "wali" dari dirinya sendiri, sehingga menu Infak Pengembangan,
-- "Data Saya", dan dasbor santri selalu tampil kosong walau akun itu jelas
-- sudah tertaut ke datanya sendiri lewat students.login_username.
-- ============================================================================
-- AKAR MASALAH:
--   Fitur wali (guardians + guardian_students) dipakai untuk membaca data di
--   /santri/infak, /santri/anak, dan dasbor /santri — TAPI tidak ada satu pun
--   jalur kode (buat guru/santri manual, import Excel, seed dummy) yang
--   pernah MENULIS ke tabel guardians/guardian_students. Akibatnya semua akun
--   santri di seluruh lembaga tampil "belum terhubung", bukan hanya kasus
--   tertentu.
--
-- PERBAIKAN (dua lapis, bukan hanya kode aplikasi — supaya berlaku untuk
-- SEMUA jalur, termasuk yang mungkin lupa ter-cover di lapisan aplikasi):
--   1. TRIGGER pada public.students: begitu login_username terisi/berubah,
--      akun (profiles, role WALI_SANTRI) dengan username yang sama otomatis
--      dijadikan "wali dari dirinya sendiri" — guardians + guardian_students
--      dibuat otomatis, tanpa langkah admin manual apa pun.
--   2. BACKFILL satu kali untuk seluruh santri yang SUDAH punya akun login
--      sebelum migrasi ini (termasuk akun yang sudah dipakai user sekarang).
--
-- Idempoten & repair-safe.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Trigger: tautkan otomatis begitu login_username terisi/berubah
-- ---------------------------------------------------------------------------
create or replace function public.students_self_guardian_link()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  v_profile_id  uuid;
  v_guardian_id uuid;
begin
  if new.login_username is null or new.login_username = '' then
    return new;
  end if;
  -- UPDATE lain (nilai/presensi, dst.) yang tidak menyentuh login_username
  -- tidak perlu memicu ulang — hemat kerja pada trigger yang sering jalan.
  if tg_op = 'UPDATE' and old.login_username is not distinct from new.login_username then
    return new;
  end if;

  select id into v_profile_id
  from public.profiles
  where username = new.login_username
    and tenant_id = new.tenant_id
    and role = 'WALI_SANTRI'
  limit 1;

  -- Profil belum ada (race jarang terjadi karena profiles selalu dibuat lebih
  -- dulu oleh createLoginAccount) — backfill di bawah akan menyusulkan nanti
  -- bila perlu; tidak menggagalkan penyimpanan data santri.
  if v_profile_id is null then
    return new;
  end if;

  insert into public.guardians (tenant_id, profile_id)
  values (new.tenant_id, v_profile_id)
  on conflict (profile_id) do nothing;

  select id into v_guardian_id from public.guardians where profile_id = v_profile_id;

  if v_guardian_id is not null then
    insert into public.guardian_students (tenant_id, guardian_id, student_id)
    values (new.tenant_id, v_guardian_id, new.id)
    on conflict (guardian_id, student_id) do nothing;
  end if;

  return new;
end;
$$;

drop trigger if exists students_self_guardian_link_trg on public.students;do $tfx$  -- idempotent: skip bila trigger sudah ada (aman dijalankan berulang)
begin
  execute 'create trigger students_self_guardian_link_trg
  after insert or update of login_username on public.students
  for each row execute function public.students_self_guardian_link()';
exception
  when duplicate_object then null;
end
$tfx$;

-- ---------------------------------------------------------------------------
-- 2. Backfill — santri yang sudah punya akun SEBELUM migrasi ini ada
-- ---------------------------------------------------------------------------
insert into public.guardians (tenant_id, profile_id)
select distinct s.tenant_id, p.id
from public.students s
join public.profiles p
  on p.username = s.login_username
 and p.tenant_id = s.tenant_id
 and p.role = 'WALI_SANTRI'
where s.login_username is not null and s.login_username <> ''
on conflict (profile_id) do nothing;

insert into public.guardian_students (tenant_id, guardian_id, student_id)
select s.tenant_id, g.id, s.id
from public.students s
join public.profiles p
  on p.username = s.login_username
 and p.tenant_id = s.tenant_id
 and p.role = 'WALI_SANTRI'
join public.guardians g on g.profile_id = p.id
where s.login_username is not null and s.login_username <> ''
on conflict (guardian_id, student_id) do nothing;
-- ============================================================================
-- SOURCE: 20260921010000_tahfizh_v17_target_halaqah.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V17 — TARGET PER HALAQAH (menggantikan Target per santri V7)
-- ============================================================================
-- Perubahan:
--   1. Target lama (per santri, V7) DIHAPUS TOTAL: tabel `targets`,
--      `target_progress_history`, seluruh RPC `target_*`, enum `target_status`,
--      serta semua tempat yang membacanya (raport, timeline perkembangan,
--      ringkasan dashboard/santri).
--   2. Target baru diatur PER HALAQAH (bukan per santri), tepat 3 jenis:
--        TAHFIDZ (Tahfidz Al-Qur'an) · HADITS · DOA
--      Satu halaqah punya paling banyak satu target per jenis
--      (unique halaqah_id + category). Satuan mengikuti jenis:
--      TAHFIDZ = surat, HADITS = hadits, DOA = doa (dipetakan di aplikasi).
--
-- Tabel  : halaqah_targets
-- RPC    : target_halaqah_overview()   — halaqah yang diampu + target-nya
--          target_halaqah_save()       — buat / ubah target (upsert per jenis)
--          target_halaqah_clear()      — kosongkan target satu jenis
--          v7_teacher_counts()         — cabang TARGETS kini = target halaqah aktif
--          v7_student_summary()        — tanpa kolom target
--          report_student_data()       — tanpa blok target
-- View   : student_development_events  — tanpa event TARGET
--
-- Keamanan: SECURITY DEFINER + verifikasi session → role USTADZ → tenant →
-- halaqah yang diampu. Tulis hanya lewat RPC; RLS select tenant + role.
-- Idempoten: aman dijalankan ulang (file gabungan menjalankan ulang semua
-- migration berurutan; urutan di bawah membuat hasil akhirnya tetap sama).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Tabel halaqah_targets
-- ----------------------------------------------------------------------------
create table if not exists public.halaqah_targets (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants (id) on delete cascade,
  halaqah_id    uuid not null references public.halaqahs (id) on delete cascade,
  category      text not null check (category in ('TAHFIDZ', 'HADITS', 'DOA')),
  target_value  integer not null check (target_value between 1 and 10000),
  start_date    date not null,
  end_date      date not null,
  description   text check (char_length(description) <= 300),
  teacher_id    uuid references public.teachers (id) on delete set null,
  created_by    uuid references public.profiles (id) on delete set null,
  updated_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (halaqah_id, category),
  constraint halaqah_targets_period_check check (end_date >= start_date)
);

create index if not exists halaqah_targets_tenant_idx
  on public.halaqah_targets (tenant_id, end_date);

drop trigger if exists halaqah_targets_updated_at on public.halaqah_targets;do $tfx$  -- idempotent: skip bila trigger sudah ada (aman dijalankan berulang)
begin
  execute 'create trigger halaqah_targets_updated_at
  before update on public.halaqah_targets
  for each row execute function public.touch_updated_at()';
exception
  when duplicate_object then null;
end
$tfx$;

alter table public.halaqah_targets enable row level security;

-- Repair-safe: drop before create (create policy is not idempotent).
drop policy if exists halaqah_targets_select on public.halaqah_targets;
create policy halaqah_targets_select on public.halaqah_targets
  for select to authenticated
  using (
    (
      tenant_id = public.current_tenant_id()
      and (
        public.current_role() in ('ADMIN', 'KOORDINATOR')
        or (
          public.current_role() = 'USTADZ'
          and exists (
            select 1 from public.halaqah_teachers ht
            where ht.halaqah_id = halaqah_targets.halaqah_id
              and ht.teacher_id = public.halaqah_current_teacher()
          )
        )
      )
    )
    or public.is_platform_developer()
  );

-- ----------------------------------------------------------------------------
-- 2. RPC target_halaqah_overview — halaqah yang diampu guru + target-nya
-- ----------------------------------------------------------------------------
drop function if exists public.target_halaqah_overview();

create or replace function public.target_halaqah_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah jsonb;
  v_targets jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select p.tenant_id, p.role::text into v_tenant, v_role
  from public.profiles p where p.id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  v_teacher := public.halaqah_current_teacher();
  if v_teacher is null then
    return jsonb_build_object('halaqah', '[]'::jsonb, 'targets', '[]'::jsonb);
  end if;

  -- Halaqah aktif yang diampu guru + jumlah santri aktif yang masih tergabung.
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', h.id,
             'name', h.name,
             'studentCount', (
               select count(*) from public.halaqah_students hs
               join public.students s on s.id = hs.student_id
               where hs.halaqah_id = h.id and hs.left_at is null and s.status = 'ACTIVE'
             )
           ) order by h.name), '[]'::jsonb)
  into v_halaqah
  from public.halaqahs h
  join public.halaqah_teachers ht on ht.halaqah_id = h.id and ht.teacher_id = v_teacher
  where h.tenant_id = v_tenant
    and h.status = 'ACTIVE';

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', t.id,
             'halaqahId', t.halaqah_id,
             'category', t.category,
             'targetValue', t.target_value,
             'startDate', t.start_date,
             'endDate', t.end_date,
             'description', t.description,
             'updatedAt', t.updated_at
           ) order by t.category), '[]'::jsonb)
  into v_targets
  from public.halaqah_targets t
  where t.tenant_id = v_tenant
    and t.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    );

  return jsonb_build_object('halaqah', v_halaqah, 'targets', v_targets);
end;
$$;

grant execute on function public.target_halaqah_overview() to authenticated;

-- ----------------------------------------------------------------------------
-- 3. RPC target_halaqah_save — buat / ubah target satu jenis untuk satu halaqah
--    Errors: AKSES_DITOLAK | GURU_TIDAK_DITEMUKAN | KATEGORI_TIDAK_VALID |
--            TARGET_TIDAK_VALID | PERIODE_TIDAK_VALID |
--            DESKRIPSI_TERLALU_PANJANG | HALAQAH_TIDAK_VALID
-- ----------------------------------------------------------------------------
drop function if exists public.target_halaqah_save(uuid, text, integer, date, date, text);

create or replace function public.target_halaqah_save(
  p_halaqah_id   uuid,
  p_category     text,
  p_target_value integer,
  p_start_date   date,
  p_end_date     date,
  p_description  text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah uuid;
  v_desc    text := nullif(btrim(coalesce(p_description, '')), '');
  v_id      uuid;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select p.tenant_id, p.role::text into v_tenant, v_role
  from public.profiles p where p.id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  v_teacher := public.halaqah_current_teacher();
  if v_teacher is null then
    raise exception 'GURU_TIDAK_DITEMUKAN';
  end if;

  if p_category is null or p_category not in ('TAHFIDZ', 'HADITS', 'DOA') then
    raise exception 'KATEGORI_TIDAK_VALID';
  end if;
  if p_target_value is null or p_target_value < 1 or p_target_value > 10000 then
    raise exception 'TARGET_TIDAK_VALID';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date < p_start_date
     or (p_end_date - p_start_date) > 1100 then
    raise exception 'PERIODE_TIDAK_VALID';
  end if;
  if v_desc is not null and char_length(v_desc) > 300 then
    raise exception 'DESKRIPSI_TERLALU_PANJANG';
  end if;

  select h.id into v_halaqah
  from public.halaqahs h
  join public.halaqah_teachers ht on ht.halaqah_id = h.id
  where h.id = p_halaqah_id
    and h.tenant_id = v_tenant
    and ht.teacher_id = v_teacher;
  if v_halaqah is null then
    raise exception 'HALAQAH_TIDAK_VALID';
  end if;

  insert into public.halaqah_targets (
    tenant_id, halaqah_id, category, target_value, start_date, end_date,
    description, teacher_id, created_by, updated_by
  ) values (
    v_tenant, v_halaqah, p_category, p_target_value, p_start_date, p_end_date,
    v_desc, v_teacher, v_uid, v_uid
  )
  on conflict (halaqah_id, category) do update set
    target_value = excluded.target_value,
    start_date   = excluded.start_date,
    end_date     = excluded.end_date,
    description  = excluded.description,
    teacher_id   = excluded.teacher_id,
    updated_by   = excluded.updated_by
  returning id into v_id;

  return v_id;
end;
$$;

grant execute on function public.target_halaqah_save(uuid, text, integer, date, date, text) to authenticated;

-- ----------------------------------------------------------------------------
-- 4. RPC target_halaqah_clear — kosongkan target satu jenis
--    Errors: AKSES_DITOLAK | GURU_TIDAK_DITEMUKAN | KATEGORI_TIDAK_VALID |
--            HALAQAH_TIDAK_VALID | TARGET_TIDAK_DITEMUKAN
-- ----------------------------------------------------------------------------
drop function if exists public.target_halaqah_clear(uuid, text);

create or replace function public.target_halaqah_clear(
  p_halaqah_id uuid,
  p_category   text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah uuid;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select p.tenant_id, p.role::text into v_tenant, v_role
  from public.profiles p where p.id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  v_teacher := public.halaqah_current_teacher();
  if v_teacher is null then
    raise exception 'GURU_TIDAK_DITEMUKAN';
  end if;

  if p_category is null or p_category not in ('TAHFIDZ', 'HADITS', 'DOA') then
    raise exception 'KATEGORI_TIDAK_VALID';
  end if;

  select h.id into v_halaqah
  from public.halaqahs h
  join public.halaqah_teachers ht on ht.halaqah_id = h.id
  where h.id = p_halaqah_id
    and h.tenant_id = v_tenant
    and ht.teacher_id = v_teacher;
  if v_halaqah is null then
    raise exception 'HALAQAH_TIDAK_VALID';
  end if;

  delete from public.halaqah_targets
  where halaqah_id = v_halaqah and category = p_category and tenant_id = v_tenant;
  if not found then
    raise exception 'TARGET_TIDAK_DITEMUKAN';
  end if;
end;
$$;

grant execute on function public.target_halaqah_clear(uuid, text) to authenticated;

-- ============================================================================
-- 5. HAPUS TOTAL TARGET LAMA (per santri, V7)
--    Urutan penting: pertama ganti SEMUA pembaca `targets` (view/fungsi),
--    baru buang fungsi, tabel, dan tipe — tanpa CASCADE.
-- ============================================================================

-- 5a. Dashboard guru: cabang TARGETS kini menghitung target halaqah yang
--     masih berlaku (end_date belum lewat) pada halaqah yang diampu guru.
create or replace function public.v7_teacher_counts(p_teacher_id uuid)
returns table (section text, cnt bigint)
language sql
security definer set search_path = public
as $$
  with session_teacher as (
    select t.id from public.teachers t
    where t.id = p_teacher_id
      and t.tenant_id = (select tenant_id from public.profiles where id = auth.uid())
      and t.full_name ilike (select full_name from public.profiles where id = auth.uid())
      and (select role from public.profiles where id = auth.uid()) = 'USTADZ'
  )
  select * from (
    select 'TARGETS'::text as section,
           count(*)::bigint as cnt
    from public.halaqah_targets ht2
    join public.halaqah_teachers hte on hte.halaqah_id = ht2.halaqah_id
    join session_teacher st on st.id = hte.teacher_id
    where ht2.end_date >= current_date
    union all
    select 'TASKS'::text,
           count(*)::bigint
    from public.tasks k, session_teacher st
    where k.teacher_id = st.id and k.deleted_at is null
      and k.status in ('BELUM_DIKERJAKAN', 'DIKERJAKAN', 'DIKUMPULKAN', 'TERLAMBAT')
    union all
    select 'JOURNALS'::text,
           count(*)::bigint
    from public.journal_entries e, session_teacher st
    where e.teacher_id = st.id and e.deleted_at is null
      and e.entry_date >= (current_date - interval '30 days')::date
  ) u;
$$;

-- 5b. Ringkasan santri: kolom target dibuang (bentuk return berubah → drop dulu).
drop function if exists public.v7_student_summary(uuid);

create or replace function public.v7_student_summary(p_student_id uuid)
returns table (
  active_tasks   integer,
  journal_month  integer
)
language sql
security definer set search_path = public
as $$
  select
    (select count(*)::integer from public.tasks k
      where k.student_id = p_student_id and k.tenant_id = public.current_tenant_id()
        and k.deleted_at is null
        and k.status in ('BELUM_DIKERJAKAN','DIKERJAKAN','DIKUMPULKAN','TERLAMBAT')),
    (select count(*)::integer from public.journal_entries e
      where e.student_id = p_student_id and e.tenant_id = public.current_tenant_id()
        and e.deleted_at is null
        and e.entry_date >= date_trunc('month', current_date)::date)
$$;

-- 5c. Raport: report_student_data tanpa blok TARGET (salinan V9 minus target).
create or replace function public.report_student_data(
  p_student_id  uuid,
  p_period_start date,
  p_period_end   date
)
returns jsonb
language plpgsql
security definer set search_path = public
as $$
declare
  v_tenant  uuid := public.current_tenant_id();
  v_student public.students;
  v_teacher public.teachers;
  v_head    public.leader_profiles;
  v_settings public.report_settings;
  v_tsettings public.tenant_settings;
  v_mode    public.tahfidz_mode;
  v_payload jsonb;
  v_tahfidz jsonb;
  v_tartil  jsonb;
  v_setoran jsonb;
  v_hadits  jsonb;
  v_doa     jsonb;
  v_tajwid  jsonb;
  v_tugas   jsonb;
  v_jurnal  jsonb;
  v_attendance jsonb;
  v_in_period date := p_period_start;
  v_out_period date := p_period_end;
begin
  if v_tenant is null then raise exception 'AKSES_DITOLAK'; end if;
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'PERIODE_TIDAK_VALID';
  end if;

  select * into v_student from public.students
  where id = p_student_id and tenant_id = v_tenant;
  if v_student is null then raise exception 'SANTRI_TIDAK_DITEMUKAN'; end if;

  select * into v_tsettings from public.tenant_settings where tenant_id = v_tenant;
  select * into v_settings from public.report_settings where tenant_id = v_tenant;
  v_mode := coalesce(public.tahfidz_settings_mode(v_tenant), 'CENTANG');

  -- TAHFIDZ (V3): surah rows + summary per V3 mode.
  v_tahfidz := (
    select jsonb_build_object(
      'count', count(*) filter (where a.status = 'DINILAI'),
      'avgValue', round(avg(a.score_value) filter (where a.status = 'DINILAI' and a.score_value is not null), 0),
      'lastLabel', (select a2.score_label from public.tahfidz_assessments a2
                    where a2.student_id = p_student_id and a2.status = 'DINILAI'
                    order by a2.assessed_at desc limit 1),
      'activeTotal', (select count(*) from public.tahfidz_tenant_surahs ts
                      where ts.tenant_id = v_tenant and ts.is_active),
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
            'name', coalesce(ts2.name_override, gs.name, 'Surat'),
            'scoreLabel', a.score_label, 'scoreValue', a.score_value, 'status', a.status)
          order by ts2.sort_order)
        from public.tahfidz_assessments a
        join public.tahfidz_tenant_surahs ts2 on ts2.id = a.tenant_surah_id
        left join public.tahfidz_surahs gs on gs.id = ts2.surah_id
        where a.student_id = p_student_id and a.status = 'DINILAI'
      ), '[]'::jsonb)
    )
    from public.tahfidz_assessments a
    where a.student_id = p_student_id
  );

  -- TARTIL (V4)
  v_tartil := (
    select jsonb_build_object(
      'count', count(*),
      'avgValue', round(avg(a.score_value), 0),
      'lastLabel', (select a2.score_label from public.tartil_assessments a2
                    where a2.student_id = p_student_id and a2.deleted_at is null
                      and a2.status = 'DINILAI'
                    order by a2.assessed_at desc limit 1),
      'lastPages', (select a2.pages_label from public.tartil_assessments a2
                    where a2.student_id = p_student_id and a2.deleted_at is null
                    order by a2.assessed_at desc limit 1)
    )
    from public.tartil_assessments a
    where a.student_id = p_student_id and a.deleted_at is null
      and a.assessed_at::date between v_in_period and v_out_period
  );

  -- SETORAN (V5)
  v_setoran := (
    select jsonb_build_object(
      'total', count(*),
      'lulus', count(*) filter (where s.result = 'LULUS'),
      'ulang', count(*) filter (where s.result = 'PERLU_MENGULANG'),
      'lastKind', (select s2.kind::text from public.tahfidz_submissions s2
                   where s2.student_id = p_student_id and s2.deleted_at is null
                   order by s2.assessed_date desc limit 1)
    )
    from public.tahfidz_submissions s
    where s.student_id = p_student_id and s.deleted_at is null
      and s.assessed_date between v_in_period and v_out_period
  );

  -- HADITS / DOA / TAJWID (V6)
  v_hadits := (
    select jsonb_build_object(
      'count', count(*) filter (where a.status in ('LULUS','MENGUASAI')),
      'total', count(*),
      'avgValue', round(avg(a.score_value), 0),
      'lastLabel', (select a2.score_label from public.learning_assessments a2
                    where a2.student_id = p_student_id and a2.deleted_at is null
                      and a2.module_type = 'HADITS'
                    order by a2.assessed_date desc limit 1)
    )
    from public.learning_assessments a
    where a.student_id = p_student_id and a.deleted_at is null
      and a.module_type = 'HADITS'
      and a.assessed_date between v_in_period and v_out_period
  );

  v_doa := (
    select jsonb_build_object(
      'count', count(*) filter (where a.status in ('LULUS','MENGUASAI')),
      'total', count(*),
      'avgValue', round(avg(a.score_value), 0),
      'lastLabel', (select a2.score_label from public.learning_assessments a2
                    where a2.student_id = p_student_id and a2.deleted_at is null
                      and a2.module_type = 'DOA'
                    order by a2.assessed_date desc limit 1)
    )
    from public.learning_assessments a
    where a.student_id = p_student_id and a.deleted_at is null
      and a.module_type = 'DOA'
      and a.assessed_date between v_in_period and v_out_period
  );

  v_tajwid := (
    select jsonb_build_object(
      'count', count(*) filter (where a.status = 'MENGUASAI'),
      'total', count(*),
      'avgValue', round(avg(a.score_value), 0),
      'lastLabel', (select a2.score_label from public.learning_assessments a2
                    where a2.student_id = p_student_id and a2.deleted_at is null
                      and a2.module_type = 'TAJWID'
                    order by a2.assessed_date desc limit 1)
    )
    from public.learning_assessments a
    where a.student_id = p_student_id and a.deleted_at is null
      and a.module_type = 'TAJWID'
      and a.assessed_date between v_in_period and v_out_period
  );

  -- TUGAS (V7)
  v_tugas := (
    select jsonb_build_object(
      'total', count(*),
      'dinilai', count(*) filter (where k.status = 'DINILAI'),
      'avgValue', round(avg(k.score_value) filter (where k.status = 'DINILAI'), 0)
    )
    from public.tasks k
    where k.student_id = p_student_id and k.deleted_at is null
      and k.due_date between v_in_period and v_out_period
  );

  -- JURNAL (V7): jumlah entry bulan periode (untuk Kartu Prestasi ringkas).
  v_jurnal := (
    select coalesce(count(*), 0)
    from public.journal_entries e
    where e.student_id = p_student_id and e.deleted_at is null
      and e.entry_date between v_in_period and v_out_period
  );

  -- PRESENSI (V8): rekap H/I/S/A + persentase untuk periode raport.
  -- rpc dipanggil via helper SQL langsung (bukan nested RPC) agar payload
  -- tetap satu query terstruktur (rule #73).
  v_attendance := (
    select jsonb_build_object(
      'hadir', count(*) filter (where r.status = 'HADIR'),
      'izin', count(*) filter (where r.status = 'IZIN'),
      'sakit', count(*) filter (where r.status = 'SAKIT'),
      'alpa', count(*) filter (where r.status = 'ALPA'),
      'persen', coalesce(round(
        count(*) filter (where r.status = 'HADIR')::numeric / nullif(count(*), 0) * 100, 0), 0)
    )
    from public.attendance_records r
    where r.student_id = p_student_id
      and r.tenant_id = v_tenant
      and r.created_at::date between v_in_period and v_out_period
  );
  select * into v_head from public.leader_profiles where tenant_id = v_tenant;

  select * into v_teacher from public.teachers
  where tenant_id = v_tenant and id = (
    select ts.teacher_id from public.teacher_students ts
    where ts.student_id = p_student_id
    order by ts.created_at desc limit 1
  );

  v_payload := jsonb_build_object(
    'student', jsonb_build_object(
      'name', v_student.full_name,
      'id', v_student.business_code,
      'gender', v_student.gender
    ),
    'teacher', case when v_teacher is null then null else jsonb_build_object(
      'name', v_teacher.full_name,
      'id', case when coalesce(v_tsettings.show_teacher_identity, false)
                 then coalesce((select ti.value from public.teacher_identities ti
                                where ti.teacher_id = v_teacher.id
                                order by ti.identity_key limit 1), '')
                 else '' end,
      'identityLabel', coalesce((select t2 ->> 'label' from public.tenant_settings ts2,
                                 jsonb_array_elements(ts2.identity_types) t2
                                 where ts2.tenant_id = v_tenant limit 1), 'ID')
    ) end,
    'head', case when v_head is null then null else jsonb_build_object(
      'name', trim(coalesce(v_head.front_title, '') || ' ' || v_head.full_name
                   || case when coalesce(v_head.back_title, '') <> '' then ', ' || v_head.back_title else '' end),
      'id', coalesce(v_head.identity_number, ''),
      'identityLabel', coalesce(v_head.identity_key, 'ID')
    ) end,
    'institution', jsonb_build_object(
      'name', (select name from public.tenants where id = v_tenant),
      'code', (select business_code from public.tenants where id = v_tenant),
      'address', coalesce(v_settings.address, ''),
      'contact', coalesce(v_settings.contact, ''),
      'logoPath', v_settings.logo_path,
      'watermark', jsonb_build_object(
        'enabled', coalesce(v_settings.watermark_enabled, false),
        'opacity', coalesce(v_settings.watermark_opacity, 15),
        'scale', coalesce(v_settings.watermark_scale, 60),
        'path', v_settings.watermark_path
      ),
      'footer', coalesce(v_settings.footer_text, ''),
      'showPageNumbers', coalesce(v_settings.show_page_numbers, true)
    ),
    'mode', v_mode::text,
    'scores', jsonb_build_object(
      'tahfidz', v_tahfidz,
      'tartil', v_tartil,
      'setoran', v_setoran,
      'hadits', v_hadits,
      'doa', v_doa,
      'tajwid', v_tajwid,
      'tugas', v_tugas,
      'jurnal', v_jurnal
    ),
    'attendance', v_attendance,  -- V8 real data (rule #65: hideable in builder)
    'period', jsonb_build_object(
      'start', v_in_period,
      'end', v_out_period
    )
  );

  return v_payload;
end;
$$;


-- 5d. Timeline perkembangan santri: tanpa event TARGET (salinan V11 minus target).
create or replace view public.student_development_events
with (security_invoker = on) as  -- RLS of underlying tables applies (no bypass)
select s.tenant_id, s.student_id, s.assessed_at::date as event_date,
       'TAHFIDZ'::text as kind,
       coalesce(ts.name_override, q.name, 'Surah') as title,
       s.status::text as detail, t.full_name as teacher,
       s.score_label, s.assessed_at as created_at
from public.tahfidz_assessments s
left join public.tahfidz_tenant_surahs ts on ts.id = s.tenant_surah_id
left join public.tahfidz_surahs q on q.id = ts.surah_id
left join public.teachers t on t.id = s.teacher_id
union all
select s.tenant_id, s.student_id, s.assessed_date, 'SETORAN',
       coalesce(ts.name_override, q.name, 'Setoran'),
       case s.kind when 'MUROJAAH' then 'Murojaah' else 'Hafalan Baru' end
         || coalesce(' · ' || s.ayat_label, '') || ' · ' || s.result::text,
       t.full_name, s.score_label, s.created_at
from public.tahfidz_submissions s
left join public.tahfidz_tenant_surahs ts on ts.id = s.tenant_surah_id
left join public.tahfidz_surahs q on q.id = ts.surah_id
left join public.teachers t on t.id = s.teacher_id
where s.deleted_at is null
union all
select s.tenant_id, s.student_id, s.assessed_at::date, 'TARTIL',
       coalesce(m.name, 'Tartil'), coalesce(s.pages_label, ''),
       t.full_name, s.score_label, s.created_at
from public.tartil_assessments s
left join public.tartil_materials m on m.id = s.material_id
left join public.teachers t on t.id = s.teacher_id
where s.deleted_at is null
union all
select s.tenant_id, s.student_id, s.assessed_date, s.module_type::text,
       coalesce(
         (select h.title from public.hadith_materials h where h.id = s.hadith_id),
         (select p.title from public.daily_prayer_materials p where p.id = s.prayer_id),
         (select w.title from public.tajwid_materials w where w.id = s.tajwid_id),
         s.module_type::text),
       s.status::text, t.full_name, s.score_label, s.created_at
from public.learning_assessments s
left join public.teachers t on t.id = s.teacher_id
where s.deleted_at is null
union all
select s.tenant_id, s.student_id, s.assigned_date, 'TUGAS',
       s.title, s.status::text, t.full_name, s.score_label, s.created_at
from public.tasks s
left join public.teachers t on t.id = s.teacher_id
where s.deleted_at is null
union all
select s.tenant_id, s.student_id, s.entry_date, 'JURNAL',
       tm.name, coalesce(s.free_text, ''), t.full_name, null, s.created_at
from public.journal_entries s
left join public.journal_templates tm on tm.id = s.template_id
left join public.teachers t on t.id = s.teacher_id
where s.deleted_at is null
union all
select ar.tenant_id, ar.student_id, as2.session_date, 'PRESENSI',
       h.name, ar.status::text || coalesce(' · ' || ar.note, ''),
       null, null, ar.created_at
from public.attendance_records ar
join public.attendance_sessions as2 on as2.id = ar.session_id
join public.halaqahs h on h.id = ar.halaqah_id
union all
select s.tenant_id, s.student_id, s.effective_date, 'MUTASI',
       'Mutasi Halaqah',
       coalesce((select h.name from public.halaqahs h where h.id = s.to_halaqah_id), '') || coalesce(' · ' || s.reason, ''),
       (select t.full_name from public.teachers t where t.id = s.to_teacher_id),
       null, s.created_at
from public.student_transfers s
union all
select s.tenant_id, s.student_id, s.created_at::date, 'PROMOSI',
       'Kenaikan Level',
       coalesce(s.from_level || ' → ', '') || s.to_level,
       null, null, s.created_at
from public.student_promotions s
union all
select s.tenant_id, s.student_id, s.effective_date, 'STATUS',
       'Perubahan Status', s.to_status::text || coalesce(' · ' || s.reason, ''),
       null, null, s.created_at
from public.student_status_history s;


-- 5e. Template raport tersimpan: buang penanda modul "TARGET" pada komponen
--     SCORE_TABLE (murni penanda; renderer tidak lagi memuat modul ini).
update public.report_templates
set layout = replace(replace(layout::text, '"TARGET", ', ''), ', "TARGET"', '')::jsonb
where layout::text like '%"TARGET"%';

-- 5f. Buang fungsi, tabel, dan tipe target lama (tidak ada pembaca tersisa).
drop function if exists public.target_save(uuid, text, date, date, text, text, numeric, text, text, uuid);
drop function if exists public.target_recompute_progress(uuid, text);
drop function if exists public.target_recompute_status(uuid, text);
drop function if exists public.target_set_progress(uuid, numeric);
drop function if exists public.target_cancel(uuid);
drop function if exists public.target_teacher_list();
drop function if exists public.target_student_detail(uuid);
drop function if exists public.target_progress_history_list(uuid);

drop table if exists public.target_progress_history;
drop table if exists public.targets;

drop function if exists public.target_record_history();
drop type if exists public.target_status;
-- ============================================================================
-- SOURCE: 20260921020000_tahfizh_v18_santri_pantauan.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V18 — PANTAUAN SANTRI
--
-- Dasbor santri (role DB: WALI_SANTRI) sebelumnya hanya punya blok ringkas di
-- halaman utama. V18 menambahkan menu pantauan mandiri yang SINKRON dengan
-- penilaian guru:
--   1. santri_prestasi_card()    → Kartu Prestasi (rekap + rata-rata + presensi)
--   2. santri_pantauan_feed()    → Pantauan Pembelajaran (semua modul, kronologis)
--   3. santri_presensi_rekap()   → Rekap Presensi per bulan
--   4. santri_target_progress()  → Target halaqah + progres pencapaian
--   5. santri_raport_list()      → Daftar raport yang sudah FINAL
--
-- Semua fungsi SECURITY DEFINER dan HANYA mengembalikan data anak yang benar-
-- benar terhubung dengan akun ini (guardian_students) di tenant-nya sendiri.
-- Tidak ada tabel/kolom yang diubah (rule #38) dan tidak ada policy yang
-- dilonggarkan — akses baca raport tetap tertutup di RLS, dibuka terbatas
-- lewat RPC ini saja.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Helper: validasi sesi wali/santri + kembalikan tenant.
-- ----------------------------------------------------------------------------
create or replace function public.santri_guard()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid;
  v_role   text;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null or v_role <> 'WALI_SANTRI' then
    raise exception 'AKSES_DITOLAK';
  end if;

  return v_tenant;
end;
$$;
grant execute on function public.santri_guard() to authenticated;

-- ============================================================================
-- 1. KARTU PRESTASI
-- ============================================================================
create or replace function public.santri_prestasi_card()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid         uuid := auth.uid();
  v_tenant      uuid := public.santri_guard();
  v_total_surah integer;
  v_out         jsonb;
begin
  select count(*) into v_total_surah
  from public.tahfidz_tenant_surahs
  where tenant_id = v_tenant and is_active;

  with anak as (
    select s.id as student_id, s.full_name as student_name, s.business_code
    from public.guardian_students gs
    join public.guardians g on g.id = gs.guardian_id
    join public.students s on s.id = gs.student_id
    where g.profile_id = v_uid and s.tenant_id = v_tenant
  ),
  halaqah as (
    select distinct on (hs.student_id)
      hs.student_id, h.name as halaqah_name
    from public.halaqah_students hs
    join public.halaqahs h on h.id = hs.halaqah_id
    join anak a on a.student_id = hs.student_id
    where hs.left_at is null
    order by hs.student_id, hs.joined_at desc
  ),
  nilai as (
    select a.student_id, x.modul, x.score_value, x.tgl, x.title
    from anak a
    join lateral (
      select 'TAHFIDZ'::text as modul, t.score_value, t.assessed_at::date as tgl,
             coalesce(ts.name_override, ms.name, 'Surat') as title
        from public.tahfidz_assessments t
        left join public.tahfidz_tenant_surahs ts on ts.id = t.tenant_surah_id
        left join public.tahfidz_surahs ms on ms.id = ts.surah_id
        where t.student_id = a.student_id and t.tenant_id = v_tenant and t.status = 'DINILAI'
      union all
      select 'TARTIL', t.score_value, t.assessed_at::date, coalesce(m.name, 'Materi Tartil')
        from public.tartil_assessments t
        left join public.tartil_materials m on m.id = t.material_id
        where t.student_id = a.student_id and t.tenant_id = v_tenant and t.deleted_at is null
      union all
      select l.module_type::text, l.score_value, l.assessed_date,
             coalesce(h.title, p2.title, tj.title, 'Materi')
        from public.learning_assessments l
        left join public.hadith_materials h on h.id = l.hadith_id
        left join public.daily_prayer_materials p2 on p2.id = l.prayer_id
        left join public.tajwid_materials tj on tj.id = l.tajwid_id
        where l.student_id = a.student_id and l.tenant_id = v_tenant and l.deleted_at is null
      union all
      select 'TUGAS', sc.score_value, sc.assessed_at::date, coalesce(tg.title, 'Tugas')
        from public.tugas_halaqah_scores sc
        left join public.tugas_halaqah tg on tg.id = sc.tugas_id
        where sc.student_id = a.student_id and sc.tenant_id = v_tenant
      union all
      select 'TAJWID', sc.score_value, sc.assessed_at::date, coalesce(tm.title, 'Materi Tajwid')
        from public.tajwid_materi_scores sc
        left join public.tajwid_materi tm on tm.id = sc.materi_id
        where sc.student_id = a.student_id and sc.tenant_id = v_tenant
      union all
      select 'SETORAN', sb.score_value, sb.assessed_date,
             coalesce(ts2.name_override, ms2.name, 'Surat')
        from public.tahfidz_submissions sb
        left join public.tahfidz_tenant_surahs ts2 on ts2.id = sb.tenant_surah_id
        left join public.tahfidz_surahs ms2 on ms2.id = ts2.surah_id
        where sb.student_id = a.student_id and sb.tenant_id = v_tenant and sb.deleted_at is null
    ) x on true
  ),
  per_modul as (
    select student_id, modul,
           count(*) as jml,
           round(avg(score_value) filter (where score_value is not null))::int as avg_score,
           max(tgl) as last_tgl,
           (array_agg(title order by tgl desc nulls last))[1] as last_title
    from nilai group by student_id, modul
  ),
  per_modul_json as (
    select student_id,
           jsonb_object_agg(modul, jsonb_build_object(
             'count', jml, 'avgScore', avg_score,
             'lastDate', last_tgl, 'lastTitle', last_title
           )) as obj
    from per_modul group by student_id
  ),
  agg as (
    select
      student_id,
      count(*)                                                     as total_penilaian,
      count(*) filter (where score_value is not null)              as ber_nilai,
      round(avg(score_value) filter (where score_value is not null))::int as avg_score,
      max(tgl)                                                     as last_tgl,
      count(*) filter (where modul = 'TAHFIDZ')                    as c_tahfidz,
      count(*) filter (where modul = 'TARTIL')                     as c_tartil,
      count(*) filter (where modul = 'HADITS')                     as c_hadits,
      count(*) filter (where modul = 'DOA')                        as c_doa,
      count(*) filter (where modul = 'TAJWID')                     as c_tajwid,
      count(*) filter (where modul = 'TUGAS')                      as c_tugas,
      count(*) filter (where modul = 'SETORAN')                    as c_setoran,
      count(*) filter (where tgl >= current_date - 30)             as c_30hari
    from nilai
    group by student_id
  ),
  hafalan as (
    select t.student_id, count(*) as surah_selesai
    from public.tahfidz_assessments t
    join anak a on a.student_id = t.student_id
    where t.tenant_id = v_tenant and t.status = 'DINILAI'
    group by t.student_id
  ),
  presensi as (
    select
      r.student_id,
      count(*)                                  as total,
      count(*) filter (where r.status = 'HADIR') as hadir,
      count(*) filter (where r.status = 'IZIN')  as izin,
      count(*) filter (where r.status = 'SAKIT') as sakit,
      count(*) filter (where r.status = 'ALPA')  as alpa
    from public.attendance_records r
    join anak a on a.student_id = r.student_id
    where r.tenant_id = v_tenant
    group by r.student_id
  ),
  apresiasi as (
    select distinct on (a.student_id)
      a.student_id, n.catatan, n.tgl
    from anak a
    join lateral (
      select t.free_note as catatan, t.assessed_at::date as tgl
        from public.tartil_assessments t
        where t.student_id = a.student_id and t.deleted_at is null
          and coalesce(t.free_note, '') <> ''
      union all
      select sb.free_note, sb.assessed_date
        from public.tahfidz_submissions sb
        where sb.student_id = a.student_id and sb.deleted_at is null
          and coalesce(sb.free_note, '') <> ''
      union all
      select l.free_note, l.assessed_date
        from public.learning_assessments l
        where l.student_id = a.student_id and l.deleted_at is null
          and coalesce(l.free_note, '') <> ''
    ) n on true
    order by a.student_id, n.tgl desc
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'studentId',      a.student_id,
        'studentName',    a.student_name,
        'businessCode',   a.business_code,
        'halaqahName',    hq.halaqah_name,
        'surahSelesai',   coalesce(hf.surah_selesai, 0),
        'surahTotal',     coalesce(v_total_surah, 0),
        'avgScore',       ag.avg_score,
        'totalPenilaian', coalesce(ag.total_penilaian, 0),
        'penilaian30Hari', coalesce(ag.c_30hari, 0),
        'lastAssessedAt', ag.last_tgl,
        'modules', jsonb_build_object(
          'TAHFIDZ', coalesce(ag.c_tahfidz, 0),
          'TARTIL',  coalesce(ag.c_tartil, 0),
          'HADITS',  coalesce(ag.c_hadits, 0),
          'DOA',     coalesce(ag.c_doa, 0),
          'TAJWID',  coalesce(ag.c_tajwid, 0),
          'TUGAS',   coalesce(ag.c_tugas, 0),
          'SETORAN', coalesce(ag.c_setoran, 0)
        ),
        'presensi', jsonb_build_object(
          'total', coalesce(pr.total, 0),
          'hadir', coalesce(pr.hadir, 0),
          'izin',  coalesce(pr.izin, 0),
          'sakit', coalesce(pr.sakit, 0),
          'alpa',  coalesce(pr.alpa, 0)
        ),
        'moduleStats', coalesce(pm.obj, '{}'::jsonb),
        'catatanApresiasi', ap.catatan
      ) order by a.student_name
    ), '[]'::jsonb)
  into v_out
  from anak a
  left join halaqah   hq on hq.student_id = a.student_id
  left join agg       ag on ag.student_id = a.student_id
  left join hafalan   hf on hf.student_id = a.student_id
  left join presensi  pr on pr.student_id = a.student_id
  left join per_modul_json pm on pm.student_id = a.student_id
  left join apresiasi ap on ap.student_id = a.student_id;

  return v_out;
end;
$$;
grant execute on function public.santri_prestasi_card() to authenticated;

-- ============================================================================
-- 2. PANTAUAN PEMBELAJARAN — semua modul, kronologis
-- ============================================================================
create or replace function public.santri_pantauan_feed(
  p_student_id uuid default null,
  p_limit      integer default 60
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid := public.santri_guard();
  v_limit  integer := least(greatest(coalesce(p_limit, 60), 1), 200);
  v_out    jsonb;
begin
  with anak as (
    select s.id as student_id, s.full_name as student_name
    from public.guardian_students gs
    join public.guardians g on g.id = gs.guardian_id
    join public.students s on s.id = gs.student_id
    where g.profile_id = v_uid
      and s.tenant_id = v_tenant
      and (p_student_id is null or s.id = p_student_id)
  ),
  feed as (
    -- Hafalan tahfidz (penilaian surat)
    select a.student_id, a.student_name, 'TAHFIDZ'::text as module,
           coalesce(ts.name_override, ms.name, 'Surat') as title,
           'Penilaian hafalan surat'::text as detail,
           t.status::text as status, t.score_label, t.score_value, t.note as free_note,
           tc.full_name as teacher_name, t.assessed_at::date as tgl
    from public.tahfidz_assessments t
    join anak a on a.student_id = t.student_id
    left join public.tahfidz_tenant_surahs ts on ts.id = t.tenant_surah_id
    left join public.tahfidz_surahs ms on ms.id = ts.surah_id
    left join public.teachers tc on tc.id = t.teacher_id
    where t.tenant_id = v_tenant

    union all
    -- Setoran hafalan / murojaah
    select a.student_id, a.student_name, 'SETORAN',
           coalesce(ts.name_override, ms.name, 'Surat'),
           concat_ws(' · ',
             case sb.kind when 'HAFALAN_BARU' then 'Hafalan Baru' else 'Murojaah' end,
             nullif(sb.ayat_label, '')),
           sb.result::text, sb.score_label, sb.score_value, sb.free_note,
           tc.full_name, sb.assessed_date
    from public.tahfidz_submissions sb
    join anak a on a.student_id = sb.student_id
    left join public.tahfidz_tenant_surahs ts on ts.id = sb.tenant_surah_id
    left join public.tahfidz_surahs ms on ms.id = ts.surah_id
    left join public.teachers tc on tc.id = sb.teacher_id
    where sb.tenant_id = v_tenant and sb.deleted_at is null

    union all
    -- Tartil (mengaji)
    select a.student_id, a.student_name, 'TARTIL',
           coalesce(m.name, 'Materi Tartil'),
           nullif(concat_ws(' ', 'Hal.', coalesce(tr.pages_label, m.pages_label)), 'Hal.'),
           tr.status::text, tr.score_label, tr.score_value, tr.free_note,
           tc.full_name, tr.assessed_at::date
    from public.tartil_assessments tr
    join anak a on a.student_id = tr.student_id
    left join public.tartil_materials m on m.id = tr.material_id
    left join public.teachers tc on tc.id = tr.teacher_id
    where tr.tenant_id = v_tenant and tr.deleted_at is null

    union all
    -- Hadits / Doa / Tajwid (modul pembelajaran)
    select a.student_id, a.student_name, l.module_type::text,
           coalesce(h.title, p.title, tj.title, 'Materi'),
           null::text,
           l.status::text, l.score_label, l.score_value, l.free_note,
           tc.full_name, l.assessed_date
    from public.learning_assessments l
    join anak a on a.student_id = l.student_id
    left join public.hadith_materials h on h.id = l.hadith_id
    left join public.daily_prayer_materials p on p.id = l.prayer_id
    left join public.tajwid_materials tj on tj.id = l.tajwid_id
    left join public.teachers tc on tc.id = l.teacher_id
    where l.tenant_id = v_tenant and l.deleted_at is null

    union all
    -- Tajwid (grid materi)
    select a.student_id, a.student_name, 'TAJWID',
           coalesce(tm.title, 'Materi Tajwid'), null::text,
           'DINILAI'::text, sc.score_label, sc.score_value, null::text,
           null::text, sc.assessed_at::date
    from public.tajwid_materi_scores sc
    join anak a on a.student_id = sc.student_id
    left join public.tajwid_materi tm on tm.id = sc.materi_id
    where sc.tenant_id = v_tenant

    union all
    -- Tugas halaqah
    select a.student_id, a.student_name, 'TUGAS',
           coalesce(tg.title, 'Tugas'),
           case when tg.due_date is not null
                then 'Batas: ' || to_char(tg.due_date, 'DD Mon YYYY') end,
           'DINILAI'::text, sc.score_label, sc.score_value, sc.note,
           tc.full_name, sc.assessed_at::date
    from public.tugas_halaqah_scores sc
    join anak a on a.student_id = sc.student_id
    left join public.tugas_halaqah tg on tg.id = sc.tugas_id
    left join public.teachers tc on tc.id = tg.teacher_id
    where sc.tenant_id = v_tenant and coalesce(tg.deleted_at, null) is null
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'studentId',   student_id,
           'studentName', student_name,
           'module',      module,
           'title',       title,
           'detail',      detail,
           'status',      status,
           'scoreLabel',  score_label,
           'scoreValue',  score_value,
           'freeNote',    free_note,
           'teacherName', teacher_name,
           'assessedDate', tgl
         ) order by tgl desc nulls last), '[]'::jsonb)
  into v_out
  from (select * from feed order by tgl desc nulls last limit v_limit) x;

  return v_out;
end;
$$;
grant execute on function public.santri_pantauan_feed(uuid, integer) to authenticated;

-- ============================================================================
-- 3. REKAP PRESENSI
-- ============================================================================
create or replace function public.santri_presensi_rekap(p_months integer default 6)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid := public.santri_guard();
  v_months integer := least(greatest(coalesce(p_months, 6), 1), 24);
  v_since  date;
  v_out    jsonb;
begin
  v_since := date_trunc('month', current_date)::date - ((v_months - 1) || ' months')::interval;

  with anak as (
    select s.id as student_id, s.full_name as student_name
    from public.guardian_students gs
    join public.guardians g on g.id = gs.guardian_id
    join public.students s on s.id = gs.student_id
    where g.profile_id = v_uid and s.tenant_id = v_tenant
  ),
  rec as (
    select a.student_id, a.student_name, r.status::text as status,
           r.note, se.session_date, h.name as halaqah_name
    from public.attendance_records r
    join anak a on a.student_id = r.student_id
    join public.attendance_sessions se on se.id = r.session_id
    left join public.halaqahs h on h.id = r.halaqah_id
    where r.tenant_id = v_tenant and se.session_date >= v_since
  ),
  per_bulan as (
    select student_id,
           to_char(session_date, 'YYYY-MM') as ym,
           min(session_date) as anchor,
           count(*) as total,
           count(*) filter (where status = 'HADIR') as hadir,
           count(*) filter (where status = 'IZIN')  as izin,
           count(*) filter (where status = 'SAKIT') as sakit,
           count(*) filter (where status = 'ALPA')  as alpa
    from rec group by student_id, to_char(session_date, 'YYYY-MM')
  ),
  total as (
    select student_id,
           count(*) as total,
           count(*) filter (where status = 'HADIR') as hadir,
           count(*) filter (where status = 'IZIN')  as izin,
           count(*) filter (where status = 'SAKIT') as sakit,
           count(*) filter (where status = 'ALPA')  as alpa
    from rec group by student_id
  ),
  terakhir as (
    select student_id, jsonb_agg(jsonb_build_object(
             'date', session_date, 'status', status,
             'note', note, 'halaqahName', halaqah_name
           ) order by session_date desc) as items
    from (
      select *, row_number() over (partition by student_id order by session_date desc) as rn
      from rec
    ) z where rn <= 10
    group by student_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'studentId',   a.student_id,
           'studentName', a.student_name,
           'summary', jsonb_build_object(
             'total', coalesce(t.total, 0), 'hadir', coalesce(t.hadir, 0),
             'izin',  coalesce(t.izin, 0),  'sakit', coalesce(t.sakit, 0),
             'alpa',  coalesce(t.alpa, 0)
           ),
           'months', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'ym', pb.ym, 'anchor', pb.anchor, 'total', pb.total,
                      'hadir', pb.hadir, 'izin', pb.izin,
                      'sakit', pb.sakit, 'alpa', pb.alpa
                    ) order by pb.ym desc)
             from per_bulan pb where pb.student_id = a.student_id
           ), '[]'::jsonb),
           'recent', coalesce(tk.items, '[]'::jsonb)
         ) order by a.student_name), '[]'::jsonb)
  into v_out
  from anak a
  left join total t     on t.student_id = a.student_id
  left join terakhir tk on tk.student_id = a.student_id;

  return v_out;
end;
$$;
grant execute on function public.santri_presensi_rekap(integer) to authenticated;

-- ============================================================================
-- 4. TARGET HALAQAH + PROGRES ANAK
-- ============================================================================
create or replace function public.santri_target_progress()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid := public.santri_guard();
  v_out    jsonb;
begin
  with anak as (
    select s.id as student_id, s.full_name as student_name
    from public.guardian_students gs
    join public.guardians g on g.id = gs.guardian_id
    join public.students s on s.id = gs.student_id
    where g.profile_id = v_uid and s.tenant_id = v_tenant
  ),
  anak_halaqah as (
    select distinct on (hs.student_id)
      hs.student_id, hs.halaqah_id, h.name as halaqah_name
    from public.halaqah_students hs
    join public.halaqahs h on h.id = hs.halaqah_id
    join anak a on a.student_id = hs.student_id
    where hs.left_at is null and h.tenant_id = v_tenant
    order by hs.student_id, hs.joined_at desc
  ),
  target as (
    select a.student_id, a.student_name, ah.halaqah_name,
           ht.id as target_id, ht.category, ht.target_value,
           ht.start_date, ht.end_date, ht.description,
           tc.full_name as teacher_name
    from anak a
    join anak_halaqah ah on ah.student_id = a.student_id
    join public.halaqah_targets ht on ht.halaqah_id = ah.halaqah_id
    left join public.teachers tc on tc.id = ht.teacher_id
    where ht.tenant_id = v_tenant
  ),
  progres as (
    select t.student_id, t.target_id,
           case t.category
             when 'TAHFIDZ' then (
               select count(*) from public.tahfidz_assessments x
               where x.student_id = t.student_id and x.tenant_id = v_tenant
                 and x.status = 'DINILAI'
                 and x.assessed_at::date between t.start_date and t.end_date
             )
             else (
               select count(*) from public.learning_assessments l
               where l.student_id = t.student_id and l.tenant_id = v_tenant
                 and l.deleted_at is null
                 and l.module_type::text = t.category
                 and l.status::text = 'LULUS'
                 and l.assessed_date between t.start_date and t.end_date
             )
           end as capaian
    from target t
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'studentId',   t.student_id,
           'studentName', t.student_name,
           'halaqahName', t.halaqah_name,
           'targetId',    t.target_id,
           'category',    t.category,
           'targetValue', t.target_value,
           'capaian',     coalesce(p.capaian, 0),
           'startDate',   t.start_date,
           'endDate',     t.end_date,
           'description', t.description,
           'teacherName', t.teacher_name
         ) order by t.student_name, t.end_date), '[]'::jsonb)
  into v_out
  from target t
  left join progres p on p.target_id = t.target_id and p.student_id = t.student_id;

  return v_out;
end;
$$;
grant execute on function public.santri_target_progress() to authenticated;

-- ============================================================================
-- 5. DAFTAR RAPORT FINAL
-- ============================================================================
create or replace function public.santri_raport_list()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid := public.santri_guard();
  v_out    jsonb;
begin
  with anak as (
    select s.id as student_id, s.full_name as student_name
    from public.guardian_students gs
    join public.guardians g on g.id = gs.guardian_id
    join public.students s on s.id = gs.student_id
    where g.profile_id = v_uid and s.tenant_id = v_tenant
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'reportId',      r.id,
           'studentId',     r.student_id,
           'studentName',   a.student_name,
           'title',         r.title,
           'academicYear',  r.academic_year,
           'semesterLabel', r.semester_label,
           'periodLabel',   r.period_label,
           'periodStart',   r.period_start,
           'periodEnd',     r.period_end,
           'finalizedAt',   r.finalized_at,
           'teacherName',   tc.full_name
         ) order by r.finalized_at desc nulls last), '[]'::jsonb)
  into v_out
  from public.reports r
  join anak a on a.student_id = r.student_id
  left join public.teachers tc on tc.id = r.teacher_id
  where r.tenant_id = v_tenant and r.status = 'FINAL';

  return v_out;
end;
$$;
grant execute on function public.santri_raport_list() to authenticated;
-- ============================================================================
-- SOURCE: 20260921030000_tahfizh_v19_santri_autolink.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V19 — Akun santri SELALU tertaut ke datanya sendiri
--
-- V16 sudah menautkan otomatis lewat trigger pada students.login_username,
-- tapi masih menyisakan celah: bila profil akun dibuat/diubah SETELAH baris
-- santri tersimpan (import, pendaftaran mandiri, login Google, perbaikan
-- username), atau bila login_username santri belum pernah diisi sama sekali,
-- akun tetap tampil "belum terhubung".
--
-- V19 menutup celah itu dengan tiga lapis:
--   1. Trigger pada public.profiles — arah sebaliknya dari V16.
--   2. RPC santri_ensure_self_link() — self-heal saat halaman santri dibuka,
--      termasuk pencocokan nama bila username belum tersimpan di baris santri.
--   3. Backfill satu kali untuk akun yang sudah ada.
--
-- Prinsipnya: akun santri pasti milik satu lembaga dan satu baris santri, jadi
-- penautan tidak pernah butuh langkah manual admin. Idempoten & repair-safe.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Helper: tautkan satu profil santri ke baris students yang sesuai.
-- Mengembalikan jumlah anak yang tertaut untuk profil tersebut.
-- ---------------------------------------------------------------------------
create or replace function public.santri_link_profile(p_profile_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_profile    public.profiles;
  v_guardian   uuid;
  v_student    uuid;
  v_count      integer := 0;
begin
  select * into v_profile from public.profiles where id = p_profile_id;
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' or v_profile.tenant_id is null then
    return 0;
  end if;

  -- Pastikan baris guardian untuk profil ini ada.
  insert into public.guardians (tenant_id, profile_id)
  values (v_profile.tenant_id, v_profile.id)
  on conflict (profile_id) do nothing;

  select id into v_guardian from public.guardians where profile_id = v_profile.id;
  if v_guardian is null then
    return 0;
  end if;

  -- (a) Cocokkan lewat username login santri — jalur utama.
  insert into public.guardian_students (tenant_id, guardian_id, student_id)
  select s.tenant_id, v_guardian, s.id
  from public.students s
  where s.tenant_id = v_profile.tenant_id
    and v_profile.username is not null
    and s.login_username = v_profile.username
  on conflict (guardian_id, student_id) do nothing;

  select count(*) into v_count
  from public.guardian_students where guardian_id = v_guardian;

  -- (b) Belum ketemu: cocokkan lewat nama lengkap, HANYA bila persis satu
  --     santri di lembaga ini bernama sama dan belum punya akun lain.
  if v_count = 0 then
    select s.id into v_student
    from public.students s
    where s.tenant_id = v_profile.tenant_id
      and lower(btrim(s.full_name)) = lower(btrim(v_profile.full_name))
      and coalesce(s.login_username, '') in ('', coalesce(v_profile.username, ''))
    limit 2;

    if (
      select count(*) from public.students s
      where s.tenant_id = v_profile.tenant_id
        and lower(btrim(s.full_name)) = lower(btrim(v_profile.full_name))
        and coalesce(s.login_username, '') in ('', coalesce(v_profile.username, ''))
    ) = 1 and v_student is not null then
      insert into public.guardian_students (tenant_id, guardian_id, student_id)
      values (v_profile.tenant_id, v_guardian, v_student)
      on conflict (guardian_id, student_id) do nothing;

      -- Sekalian simpan username-nya agar jalur (a) berlaku seterusnya.
      if v_profile.username is not null then
        update public.students
        set login_username = v_profile.username
        where id = v_student and coalesce(login_username, '') = '';
      end if;
    end if;

    select count(*) into v_count
    from public.guardian_students where guardian_id = v_guardian;
  end if;

  return v_count;
end;
$$;
grant execute on function public.santri_link_profile(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 1. Trigger pada profiles — arah kebalikan dari trigger V16.
-- ---------------------------------------------------------------------------
create or replace function public.profiles_self_guardian_link()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role = 'WALI_SANTRI' and new.tenant_id is not null then
    perform public.santri_link_profile(new.id);
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_self_guardian_link_trg on public.profiles;do $tfx$  -- idempotent: skip bila trigger sudah ada (aman dijalankan berulang)
begin
  execute 'create trigger profiles_self_guardian_link_trg
  after insert or update of username, role, tenant_id, full_name on public.profiles
  for each row execute function public.profiles_self_guardian_link()';
exception
  when duplicate_object then null;
end
$tfx$;

-- ---------------------------------------------------------------------------
-- 2. Self-heal saat halaman santri dibuka (dipanggil dari layout /santri).
-- ---------------------------------------------------------------------------
create or replace function public.santri_ensure_self_link()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return 0;
  end if;
  return public.santri_link_profile(v_uid);
end;
$$;
grant execute on function public.santri_ensure_self_link() to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Backfill semua akun santri yang sudah ada.
-- ---------------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select id from public.profiles
    where role = 'WALI_SANTRI' and tenant_id is not null
  loop
    perform public.santri_link_profile(r.id);
  end loop;
end $$;
-- ============================================================================
-- SOURCE: 20260921040000_tahfizh_v20_obrolan_chat.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V20 — OBROLAN (chat 1 lembaga, otomatis terhapus 24 jam)
--
-- Ruang obrolan tunggal per lembaga — semua peran di tenant yang sama
-- (Admin/Koordinator/Ustadz/Santri) berbagi satu ruang, TIDAK PERNAH lintas
-- lembaga. Pesan hanya bertahan 24 jam:
--   1. Setiap kali seseorang mengirim pesan, pesan tenant tsb yang sudah
--      lewat 24 jam langsung dibersihkan (self-purging, tidak bergantung
--      pg_cron).
--   2. Semua pembacaan (chat_list) memfilter created_at >= now() - 24 jam,
--      jadi walau baris lama sempat tersisa, tidak akan pernah tampil.
--   3. Bila ekstensi pg_cron tersedia, dijadwalkan pembersihan tambahan tiap
--      jam untuk SEMUA tenant sekaligus (mengikuti pola V12 invoice cron).
--
-- Role DEVELOPER (platform, tidak terikat satu lembaga) TIDAK diberi menu
-- Obrolan — current_tenant_id() developer bernilai NULL, sehingga secara
-- alami tidak cocok dengan tenant_id manapun (bukan pengecualian khusus).
-- ============================================================================

create table if not exists public.chat_messages (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants (id) on delete cascade,
  sender_id   uuid not null references public.profiles (id) on delete cascade,
  sender_name text not null check (char_length(sender_name) between 1 and 120),
  sender_role public.app_role not null,
  content     text not null check (char_length(btrim(content)) between 1 and 1000),
  created_at  timestamptz not null default now()
);

create index if not exists chat_messages_tenant_created_idx
  on public.chat_messages (tenant_id, created_at desc);

alter table public.chat_messages enable row level security;

-- Baca/tulis hanya di tenant sendiri — batas "1 lembaga" ditegakkan di RLS,
-- bukan hanya di RPC, supaya tidak bisa dilewati lewat jalur lain.
drop policy if exists chat_messages_select on public.chat_messages;
create policy chat_messages_select on public.chat_messages
  for select to authenticated
  using (tenant_id = public.current_tenant_id());

drop policy if exists chat_messages_insert on public.chat_messages;
create policy chat_messages_insert on public.chat_messages
  for insert to authenticated
  with check (tenant_id = public.current_tenant_id() and sender_id = auth.uid());

-- Hapus: pengirim sendiri, atau ADMIN/KOORDINATOR tenant tsb (moderasi).
drop policy if exists chat_messages_delete on public.chat_messages;
create policy chat_messages_delete on public.chat_messages
  for delete to authenticated
  using (
    tenant_id = public.current_tenant_id()
    and (sender_id = auth.uid() or public.current_role() in ('ADMIN', 'KOORDINATOR'))
  );

-- ---------------------------------------------------------------------------
-- Kirim pesan — validasi, purge pesan >24 jam milik tenant sendiri, insert.
-- ---------------------------------------------------------------------------
create or replace function public.chat_send(p_content text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_name    text;
  v_role    public.app_role;
  v_content text := btrim(coalesce(p_content, ''));
  v_row     public.chat_messages;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if char_length(v_content) < 1 then
    raise exception 'PESAN_KOSONG';
  end if;
  if char_length(v_content) > 1000 then
    v_content := left(v_content, 1000);
  end if;

  select tenant_id, full_name, role into v_tenant, v_name, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  -- Self-purging: setiap pesan baru sekalian membersihkan pesan tenant ini
  -- yang sudah lewat 24 jam. Tidak bergantung pg_cron untuk tetap ringkas.
  delete from public.chat_messages
  where tenant_id = v_tenant and created_at < now() - interval '24 hours';

  insert into public.chat_messages (tenant_id, sender_id, sender_name, sender_role, content)
  values (v_tenant, v_uid, v_name, v_role, v_content)
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id, 'senderId', v_row.sender_id, 'senderName', v_row.sender_name,
    'senderRole', v_row.sender_role, 'content', v_row.content, 'createdAt', v_row.created_at,
    'isSelf', true
  );
end;
$$;
grant execute on function public.chat_send(text) to authenticated;

-- ---------------------------------------------------------------------------
-- Ambil pesan — hanya 24 jam terakhir. p_since untuk polling inkremental
-- (hanya pesan setelah timestamp itu); tanpa p_since = muat awal (maks 200).
-- ---------------------------------------------------------------------------
create or replace function public.chat_list(p_since timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid;
  v_out    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id into v_tenant from public.profiles where id = v_uid;
  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  if p_since is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'senderId', m.sender_id, 'senderName', m.sender_name,
             'senderRole', m.sender_role, 'content', m.content, 'createdAt', m.created_at,
             'isSelf', m.sender_id = v_uid
           ) order by m.created_at asc), '[]'::jsonb)
    into v_out
    from public.chat_messages m
    where m.tenant_id = v_tenant
      and m.created_at >= now() - interval '24 hours'
      and m.created_at > p_since;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'senderId', m.sender_id, 'senderName', m.sender_name,
             'senderRole', m.sender_role, 'content', m.content, 'createdAt', m.created_at,
             'isSelf', m.sender_id = v_uid
           ) order by m.created_at asc), '[]'::jsonb)
    into v_out
    from (
      select * from public.chat_messages m
      where m.tenant_id = v_tenant and m.created_at >= now() - interval '24 hours'
      order by m.created_at desc
      limit 200
    ) m;
  end if;

  return v_out;
end;
$$;
grant execute on function public.chat_list(timestamptz) to authenticated;

-- ---------------------------------------------------------------------------
-- Hapus pesan sendiri (atau moderasi ADMIN/KOORDINATOR) — RLS di atas yang
-- menegakkan siapa boleh menghapus apa; fungsi ini hanya pembungkus praktis.
-- ---------------------------------------------------------------------------
create or replace function public.chat_delete(p_message_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.chat_messages where id = p_message_id;
  return found;
end;
$$;
grant execute on function public.chat_delete(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- Pembersihan lintas-tenant (jaring pengaman tambahan bila pg_cron ada).
-- ---------------------------------------------------------------------------
create or replace function public.chat_purge_all_expired()
returns void
language sql
security definer
set search_path = public
as $$
  delete from public.chat_messages where created_at < now() - interval '24 hours';
$$;
grant execute on function public.chat_purge_all_expired() to authenticated;

do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.unschedule(jobid) from cron.job where jobname = 'tahfizh-chat-purge';
    perform cron.schedule('tahfizh-chat-purge', '5 * * * *', 'select public.chat_purge_all_expired()');
  else
    raise notice 'pg_cron tidak tersedia — pembersihan Obrolan tetap berjalan otomatis lewat chat_send() setiap ada pesan masuk.';
  end if;
exception when others then
  raise notice 'Jadwal pg_cron Obrolan dilewati (%) — fallback self-purge di chat_send() tetap berjalan.', sqlerrm;
end $$;
-- ============================================================================
-- SOURCE: 20260921050000_tahfizh_v21_obrolan_halaqah_rooms.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V21 — Obrolan: ruang per Halaqah + batas 160 karakter
--
-- V20 hanya punya satu ruang per lembaga. V21 menambahkan ruang tambahan per
-- Halaqah (halaqah_id NULL tetap berarti ruang "Lembaga" — semua anggota
-- tenant). Siapa boleh masuk ruang Halaqah mana ditentukan oleh peran:
--   - ADMIN/KOORDINATOR : semua Halaqah aktif di lembaganya (pengawasan).
--   - USTADZ             : Halaqah yang ia ajar (halaqah_teachers).
--   - WALI_SANTRI         : Halaqah tempat anaknya terdaftar aktif.
-- Batas "1 lembaga" dari V20 tetap berlaku penuh untuk kedua jenis ruang.
-- Panjang pesan diperketat dari 1000 -> 160 karakter.
-- ============================================================================

alter table public.chat_messages
  add column if not exists halaqah_id uuid references public.halaqahs (id) on delete cascade;

create index if not exists chat_messages_room_idx
  on public.chat_messages (tenant_id, halaqah_id, created_at desc);

-- Perketat batas panjang pesan: 1000 -> 160 karakter.
alter table public.chat_messages drop constraint if exists chat_messages_content_check;
alter table public.chat_messages
  add constraint chat_messages_content_check check (char_length(btrim(content)) between 1 and 160);

-- ---------------------------------------------------------------------------
-- Helper: apakah pengguna saat ini boleh mengakses ruang Halaqah tertentu.
-- ---------------------------------------------------------------------------
create or replace function public.chat_can_access_halaqah(p_halaqah_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid           uuid := auth.uid();
  v_tenant        uuid := public.current_tenant_id();
  v_role          public.app_role := public.current_role();
  v_halaqah_tenant uuid;
begin
  if v_uid is null or v_tenant is null or p_halaqah_id is null then
    return false;
  end if;

  select tenant_id into v_halaqah_tenant from public.halaqahs where id = p_halaqah_id;
  if v_halaqah_tenant is null or v_halaqah_tenant <> v_tenant then
    return false;
  end if;

  if v_role in ('ADMIN', 'KOORDINATOR') then
    return true;
  end if;

  if v_role = 'USTADZ' then
    return exists (
      select 1 from public.halaqah_teachers ht
      join public.teachers t on t.id = ht.teacher_id
      where ht.halaqah_id = p_halaqah_id and t.profile_id = v_uid
    );
  end if;

  if v_role = 'WALI_SANTRI' then
    return exists (
      select 1 from public.halaqah_students hs
      join public.guardian_students gs on gs.student_id = hs.student_id
      join public.guardians g on g.id = gs.guardian_id
      where hs.halaqah_id = p_halaqah_id and hs.left_at is null and g.profile_id = v_uid
    );
  end if;

  return false;
end;
$$;
grant execute on function public.chat_can_access_halaqah(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- RLS — tambahkan syarat akses ruang Halaqah di atas syarat 1-tenant lama.
-- ---------------------------------------------------------------------------
drop policy if exists chat_messages_select on public.chat_messages;
create policy chat_messages_select on public.chat_messages
  for select to authenticated
  using (
    tenant_id = public.current_tenant_id()
    and (halaqah_id is null or public.chat_can_access_halaqah(halaqah_id))
  );

drop policy if exists chat_messages_insert on public.chat_messages;
create policy chat_messages_insert on public.chat_messages
  for insert to authenticated
  with check (
    tenant_id = public.current_tenant_id()
    and sender_id = auth.uid()
    and (halaqah_id is null or public.chat_can_access_halaqah(halaqah_id))
  );

-- ---------------------------------------------------------------------------
-- Daftar ruang yang boleh dibuka pengguna saat ini: "Lembaga" + Halaqah yang
-- relevan dengan perannya.
-- ---------------------------------------------------------------------------
create or replace function public.chat_rooms()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid;
  v_role   public.app_role;
  v_out    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id, role into v_tenant, v_role from public.profiles where id = v_uid;
  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  with halaqah_list as (
    select h.id, h.name
    from public.halaqahs h
    where h.tenant_id = v_tenant and h.status = 'ACTIVE'
      and (
        v_role in ('ADMIN', 'KOORDINATOR')
        or (
          v_role = 'USTADZ' and exists (
            select 1 from public.halaqah_teachers ht
            join public.teachers t on t.id = ht.teacher_id
            where ht.halaqah_id = h.id and t.profile_id = v_uid
          )
        )
        or (
          v_role = 'WALI_SANTRI' and exists (
            select 1 from public.halaqah_students hs
            join public.guardian_students gs on gs.student_id = hs.student_id
            join public.guardians g on g.id = gs.guardian_id
            where hs.halaqah_id = h.id and hs.left_at is null and g.profile_id = v_uid
          )
        )
      )
  )
  select
    jsonb_build_array(jsonb_build_object('id', null, 'label', 'Lembaga', 'kind', 'tenant'))
    || coalesce(
         (select jsonb_agg(jsonb_build_object('id', id, 'label', name, 'kind', 'halaqah') order by name)
          from halaqah_list),
         '[]'::jsonb
       )
  into v_out;

  return v_out;
end;
$$;
grant execute on function public.chat_rooms() to authenticated;

-- ---------------------------------------------------------------------------
-- chat_send / chat_list — tambah parameter ruang (p_halaqah_id) + batas 160.
-- Signature berubah (parameter baru), jadi fungsi lama dibuang dulu.
-- ---------------------------------------------------------------------------
drop function if exists public.chat_send(text);
drop function if exists public.chat_list(timestamptz);

create or replace function public.chat_send(p_content text, p_halaqah_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_name    text;
  v_role    public.app_role;
  v_content text := btrim(coalesce(p_content, ''));
  v_row     public.chat_messages;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if char_length(v_content) < 1 then
    raise exception 'PESAN_KOSONG';
  end if;
  if char_length(v_content) > 160 then
    v_content := left(v_content, 160);
  end if;

  select tenant_id, full_name, role into v_tenant, v_name, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  if p_halaqah_id is not null and not public.chat_can_access_halaqah(p_halaqah_id) then
    raise exception 'AKSES_DITOLAK';
  end if;

  -- Self-purging: setiap pesan baru sekalian membersihkan pesan tenant ini
  -- (semua ruang) yang sudah lewat 24 jam.
  delete from public.chat_messages
  where tenant_id = v_tenant and created_at < now() - interval '24 hours';

  insert into public.chat_messages (tenant_id, halaqah_id, sender_id, sender_name, sender_role, content)
  values (v_tenant, p_halaqah_id, v_uid, v_name, v_role, v_content)
  returning * into v_row;

  return jsonb_build_object(
    'id', v_row.id, 'halaqahId', v_row.halaqah_id, 'senderId', v_row.sender_id,
    'senderName', v_row.sender_name, 'senderRole', v_row.sender_role,
    'content', v_row.content, 'createdAt', v_row.created_at, 'isSelf', true
  );
end;
$$;
grant execute on function public.chat_send(text, uuid) to authenticated;

create or replace function public.chat_list(p_since timestamptz default null, p_halaqah_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid    uuid := auth.uid();
  v_tenant uuid;
  v_out    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id into v_tenant from public.profiles where id = v_uid;
  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  if p_halaqah_id is not null and not public.chat_can_access_halaqah(p_halaqah_id) then
    raise exception 'AKSES_DITOLAK';
  end if;

  if p_since is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'halaqahId', m.halaqah_id, 'senderId', m.sender_id,
             'senderName', m.sender_name, 'senderRole', m.sender_role,
             'content', m.content, 'createdAt', m.created_at, 'isSelf', m.sender_id = v_uid
           ) order by m.created_at asc), '[]'::jsonb)
    into v_out
    from public.chat_messages m
    where m.tenant_id = v_tenant
      and m.halaqah_id is not distinct from p_halaqah_id
      and m.created_at >= now() - interval '24 hours'
      and m.created_at > p_since;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', m.id, 'halaqahId', m.halaqah_id, 'senderId', m.sender_id,
             'senderName', m.sender_name, 'senderRole', m.sender_role,
             'content', m.content, 'createdAt', m.created_at, 'isSelf', m.sender_id = v_uid
           ) order by m.created_at asc), '[]'::jsonb)
    into v_out
    from (
      select * from public.chat_messages m
      where m.tenant_id = v_tenant
        and m.halaqah_id is not distinct from p_halaqah_id
        and m.created_at >= now() - interval '24 hours'
      order by m.created_at desc
      limit 200
    ) m;
  end if;

  return v_out;
end;
$$;
grant execute on function public.chat_list(timestamptz, uuid) to authenticated;
-- ============================================================================
-- SOURCE: 20260921060000_tahfizh_v21_fix_target_halaqah_status.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V21.1 — PERBAIKAN: menu Target guru kosong padahal sudah mengampu
-- ============================================================================
-- Bug: target_halaqah_overview() (V17) memfilter `h.status = 'ACTIVE'` saat
-- mengambil daftar halaqah yang diampu guru. Halaman lain yang menampilkan
-- "halaqah yang diampu" (mis. halaqah_teacher_list — menu "Halaqah Saya")
-- TIDAK memfilter status ini, jadi begitu admin menonaktifkan sebuah halaqah
-- (tombol "Nonaktifkan" di manajer halaqah admin) guru yang masih tercatat
-- sebagai pengampu (baris di halaqah_teachers tidak dihapus saat nonaktif)
-- tetap melihat halaqah itu di "Halaqah Saya", tapi menu Target menampilkan
-- "Belum ada halaqah yang Anda ampu" — tidak konsisten dan membingungkan guru
-- yang yakin sudah mengampu.
--
-- Perbaikan: samakan perilaku dengan halaqah_teacher_list — tampilkan semua
-- halaqah yang diampu guru (aktif maupun nonaktif) di overview Target. Guru
-- tetap bisa membuat/mengubah target untuk halaqah tersebut (target_halaqah_save
-- tidak pernah memfilter status halaqah, hanya keanggotaan pengampu), jadi
-- menghapus filter ini juga menghilangkan ketidakcocokan submit vs tampilan.
-- Idempoten: create or replace, aman dijalankan ulang.
-- ============================================================================

create or replace function public.target_halaqah_overview()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah jsonb;
  v_targets jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select p.tenant_id, p.role::text into v_tenant, v_role
  from public.profiles p where p.id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  v_teacher := public.halaqah_current_teacher();
  if v_teacher is null then
    return jsonb_build_object('halaqah', '[]'::jsonb, 'targets', '[]'::jsonb);
  end if;

  -- V21.1: halaqah yang diampu guru (aktif maupun nonaktif — sama seperti
  -- halaqah_teacher_list / menu "Halaqah Saya") + jumlah santri aktif yang
  -- masih tergabung.
  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', h.id,
             'name', h.name,
             'studentCount', (
               select count(*) from public.halaqah_students hs
               join public.students s on s.id = hs.student_id
               where hs.halaqah_id = h.id and hs.left_at is null and s.status = 'ACTIVE'
             )
           ) order by h.name), '[]'::jsonb)
  into v_halaqah
  from public.halaqahs h
  join public.halaqah_teachers ht on ht.halaqah_id = h.id and ht.teacher_id = v_teacher
  where h.tenant_id = v_tenant;

  select coalesce(jsonb_agg(
           jsonb_build_object(
             'id', t.id,
             'halaqahId', t.halaqah_id,
             'category', t.category,
             'targetValue', t.target_value,
             'startDate', t.start_date,
             'endDate', t.end_date,
             'description', t.description,
             'updatedAt', t.updated_at
           ) order by t.category), '[]'::jsonb)
  into v_targets
  from public.halaqah_targets t
  where t.tenant_id = v_tenant
    and t.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    );

  return jsonb_build_object('halaqah', v_halaqah, 'targets', v_targets);
end;
$$;

grant execute on function public.target_halaqah_overview() to authenticated;
-- ============================================================================
-- SOURCE: 20260921070000_tahfizh_v25_teacher_dashboard_capaian.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V25 — Rata-Rata Capaian Halaqah pada dasbor guru
--
-- Menambahkan `avgAchievement` (0-100, atau null bila belum ada data) ke
-- v8_teacher_dashboard(): persentase rata-rata surah yang sudah berstatus
-- DINILAI dari total surah aktif tenant, dirata-ratakan di seluruh santri
-- aktif pada halaqah yang diampu guru. Metrik ini independen dari mode
-- penilaian (CENTANG/HURUF/ANGKA) karena hanya memakai kolom `status`
-- (rule #25), jadi tetap valid untuk semua tenant.
-- ============================================================================

create or replace function public.v8_teacher_dashboard()
returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare
  v_teacher uuid := public.halaqah_current_teacher();
  v_tenant uuid := public.current_tenant_id();
  v_halaqah int;
  v_students int;
  v_present int;
  v_total_today int;
  v_active_surahs int;
  v_avg_achievement numeric;
begin
  if v_teacher is null or v_tenant is null then
    return jsonb_build_object(
      'halaqah', 0, 'students', 0, 'presentToday', 0, 'totalToday', 0, 'avgAchievement', null
    );
  end if;

  select count(distinct ht.halaqah_id) into v_halaqah
  from public.halaqah_teachers ht
  join public.halaqahs h on h.id = ht.halaqah_id
  where ht.teacher_id = v_teacher and h.tenant_id = v_tenant and h.status = 'ACTIVE';

  select count(distinct hs.student_id) into v_students
  from public.halaqah_students hs
  join public.halaqahs h on h.id = hs.halaqah_id
  join public.halaqah_teachers ht on ht.halaqah_id = h.id
  where ht.teacher_id = v_teacher and hs.left_at is null and h.tenant_id = v_tenant;

  select
    count(*) filter (where r.status = 'HADIR'),
    count(*)
  into v_present, v_total_today
  from public.attendance_records r
  join public.attendance_sessions s on s.id = r.session_id
  join public.halaqah_teachers ht on ht.halaqah_id = s.halaqah_id
  where ht.teacher_id = v_teacher and s.session_date = current_date;

  -- Rata-rata capaian: % surah aktif tenant yang sudah DINILAI, per santri
  -- aktif di halaqah guru, lalu dirata-ratakan.
  select count(*) into v_active_surahs
  from public.tahfidz_tenant_surahs
  where tenant_id = v_tenant and is_active = true;

  if v_active_surahs > 0 then
    with active_students as (
      select distinct hs.student_id
      from public.halaqah_students hs
      join public.halaqahs h on h.id = hs.halaqah_id
      join public.halaqah_teachers ht on ht.halaqah_id = h.id
      where ht.teacher_id = v_teacher and hs.left_at is null and h.tenant_id = v_tenant
    ),
    per_student as (
      select
        a.student_id,
        count(ta.id) filter (where ta.status = 'DINILAI') as done
      from active_students a
      left join public.tahfidz_assessments ta
        on ta.student_id = a.student_id and ta.tenant_id = v_tenant
      group by a.student_id
    )
    select avg(done::numeric / v_active_surahs * 100)
    into v_avg_achievement
    from per_student;
  end if;

  return jsonb_build_object(
    'halaqah', v_halaqah, 'students', v_students,
    'presentToday', v_present, 'totalToday', v_total_today,
    'avgAchievement', case when v_avg_achievement is null then null else round(v_avg_achievement) end
  );
end;
$$;

grant execute on function public.v8_teacher_dashboard() to authenticated;
-- ============================================================================
-- SOURCE: 20260921080000_tahfizh_v26_infak_grace_lembaga_baru.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V26 — INFAK PENGEMBANGAN: MASA TENGGANG LEMBAGA BARU
-- ============================================================================
-- Aturan baru:
--   Jika sebuah lembaga (tenant) baru mendaftar SETELAH tanggal 15 pada suatu
--   bulan, maka tagihan infak pengembangan pertamanya BUKAN untuk bulan itu,
--   melainkan baru muncul tanggal 1 bulan berikutnya. Dengan begitu akun wali
--   lembaga tersebut TIDAK langsung terkunci hanya karena baru mendaftar di
--   akhir bulan (jatuh temponya sudah lewat tanggal 15 saat tagihan dibuat).
--
--   Jika lembaga mendaftar pada tanggal 1-15, tidak ada perubahan perilaku:
--   tagihan bulan berjalan tetap dibuat seperti biasa, jatuh tempo tanggal 15,
--   dan akun terkunci mulai tanggal 16 bila belum lunas (gate lama, tetap).
--
--   Untuk lembaga yang mendaftar setelah tanggal 15:
--     - Bulan pendaftaran: TIDAK ada tagihan (tidak dihitung, tidak dikunci).
--     - Tagihan pertama muncul tanggal 1 bulan berikutnya, jatuh tempo
--       tanggal 15 bulan itu, dan akun terkunci mulai tanggal 16 bila belum
--       lunas — sama seperti lembaga lain.
--
-- Implementasi: public.tenant_billing_start_month(created_at) menghitung
-- bulan pertama lembaga itu wajib ditagih (berdasarkan tanggal 15, zona
-- waktu Asia/Jakarta). invoice_generate_all() dan invoice_ensure_for_guardian()
-- memakainya sebagai syarat tambahan sebelum membuat tagihan.
--
-- Perbaikan data: menghapus tagihan bulan berjalan yang SUDAH TERLANJUR
-- dibuat (dan belum dibayar) untuk lembaga yang baru mendaftar setelah
-- tanggal 15 pada bulan yang sama, supaya akunnya tidak terkunci karena
-- tagihan yang seharusnya belum boleh terbit.
-- Aman dijalankan ulang (idempoten). Tidak ada drop tabel / kolom.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Fungsi: bulan pertama lembaga wajib ditagih infak pengembangan.
--    Daftar tanggal 1-15  -> bulan yang sama.
--    Daftar tanggal 16-31 -> bulan berikutnya.
-- ---------------------------------------------------------------------------
create or replace function public.tenant_billing_start_month(p_created_at timestamptz)
returns date language sql stable as $$
  select case
    when extract(day from (p_created_at at time zone 'Asia/Jakarta')) > 15
      then (date_trunc('month', (p_created_at at time zone 'Asia/Jakarta')) + interval '1 month')::date
    else date_trunc('month', (p_created_at at time zone 'Asia/Jakarta'))::date
  end
$$;

revoke all on function public.tenant_billing_start_month(timestamptz) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. invoice_generate_all — tambahkan syarat masa tenggang lembaga baru.
-- ---------------------------------------------------------------------------
create or replace function public.invoice_generate_all(
  p_year  integer default null,
  p_month integer default null
)
returns integer language plpgsql security definer set search_path = public as $$
declare
  v_today record;
  v_amount integer;
  v_count integer := 0;
begin
  select * into v_today from public.jakarta_today();
  p_year  := coalesce(p_year, v_today.y);
  p_month := coalesce(p_month, v_today.m);

  select default_amount into v_amount from public.platform_payment_settings where id;
  v_amount := greatest(coalesce(v_amount, 1000), 1000);

  with ins as (
    insert into public.payment_invoices (tenant_id, student_id, academic_year, year, month, amount)
    select s.tenant_id, s.id,
           case when p_month >= 7 then p_year::text || '/' || (p_year + 1)::text
                else (p_year - 1)::text || '/' || p_year::text end,
           p_year, p_month, v_amount
    from public.students s
    join public.tenants t on t.id = s.tenant_id and t.status = 'ACTIVE'
    where s.status = 'ACTIVE'
      and make_date(p_year, p_month, 1) >= public.tenant_billing_start_month(t.created_at)
      and not exists (
        select 1 from public.payment_invoices i
        where i.student_id = s.id and i.year = p_year and i.month = p_month
      )
    on conflict (tenant_id, student_id, academic_year, year, month) do nothing
    returning 1
  )
  select count(*) into v_count from ins;

  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. invoice_ensure_for_guardian — syarat yang sama untuk fallback per-wali.
-- ---------------------------------------------------------------------------
create or replace function public.invoice_ensure_for_guardian(p_guardian_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_today record;
  v_amount integer;
begin
  select * into v_today from public.jakarta_today();
  select default_amount into v_amount from public.platform_payment_settings where id;
  v_amount := greatest(coalesce(v_amount, 1000), 1000);

  insert into public.payment_invoices (tenant_id, student_id, academic_year, year, month, amount)
  select s.tenant_id, s.id,
         case when v_today.m >= 7 then v_today.y::text || '/' || (v_today.y + 1)::text
              else (v_today.y - 1)::text || '/' || v_today.y::text end,
         v_today.y, v_today.m, v_amount
  from public.guardian_students gs
  join public.students s on s.id = gs.student_id and s.status = 'ACTIVE'
  join public.tenants t on t.id = s.tenant_id and t.status = 'ACTIVE'
  where gs.guardian_id = p_guardian_id
    and make_date(v_today.y, v_today.m, 1) >= public.tenant_billing_start_month(t.created_at)
    and not exists (
      select 1 from public.payment_invoices i
      where i.student_id = s.id and i.year = v_today.y and i.month = v_today.m
    )
  on conflict (tenant_id, student_id, academic_year, year, month) do nothing;
end;
$$;

revoke all on function public.invoice_generate_all(integer, integer) from public, anon, authenticated;
revoke all on function public.invoice_ensure_for_guardian(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Perbaikan data: hapus tagihan yang terlanjur terbit di luar masa
--    tenggang (belum lunas) — hanya menyentuh tagihan UNPAID/PENDING milik
--    lembaga yang mendaftar setelah tanggal 15 pada bulan tagihan itu sendiri.
--    Tagihan yang sudah PAID/WAITING_CONFIRM tidak disentuh.
-- ---------------------------------------------------------------------------
delete from public.payment_invoices i
using public.tenants t
where i.tenant_id = t.id
  and i.status in ('UNPAID', 'PENDING')
  and make_date(i.year, i.month, 1) < public.tenant_billing_start_month(t.created_at);
-- ============================================================================
-- SOURCE: 20260921120000_tahfizh_v27_infak_pelunasan_developer.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V27 — INFAK PENGEMBANGAN: PELUNASAN OLEH DEVELOPER + ATAS NAMA
-- ============================================================================
-- Aturan baru:
--   1. DEVELOPER dapat MELUNASI tagihan infak pengembangan santri secara
--      langsung (pembayaran diterima di luar aplikasi: tunai, transfer ke
--      rekening lain, donatur, dsb.) dan WAJIB menuliskan DIBAYARKAN OLEH
--      SIAPA. Nama pembayar itu tampil di dasbor/riwayat santri yang
--      bersangkutan ("Dibayarkan tanggal … oleh …").
--        - metode transaksi baru: 'OFFLINE' (pelunasan dicatat Developer);
--        - satu transaksi per lembaga, banyak santri × banyak bulan sekaligus;
--        - idempoten per tagihan: tagihan yang sudah PAID ditolak.
--   2. Kolom baru payment_transactions.payer_alias = "dibayarkan atas nama".
--      Dipakai dua hal:
--        - pelunasan Developer  -> nama donatur/pembayar yang dituliskan;
--        - wali membayarkan santri lain -> boleh memakai nama lain /
--          "Hamba Allah" (infak anonim) tanpa menghilangkan jejak audit,
--          karena payer_name & payer_profile_id tetap identitas asli.
--      Semua tampilan ke santri memakai coalesce(payer_alias, payer_name).
--   3. Daftar tunggakan untuk Developer (payment_dev_arrears): seluruh santri
--      dari semua lembaga yang belum membayar, diurutkan dari tunggakan
--      PALING LAMA, dengan filter lembaga & pencarian nama/kode.
-- Aman dijalankan ulang (idempoten). Tidak ada drop tabel / kolom / data.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Skema: metode OFFLINE + kolom "atas nama"
-- ---------------------------------------------------------------------------
alter table public.payment_transactions
  add column if not exists payer_alias text;

comment on column public.payment_transactions.payer_alias is
  'V27: nama yang ditampilkan ke santri sebagai pembayar ("dibayarkan oleh …"). '
  'NULL = pakai payer_name. payer_name/payer_profile_id tetap identitas asli (audit).';

alter table public.payment_transactions
  drop constraint if exists payment_transactions_method_check;
alter table public.payment_transactions
  add constraint payment_transactions_method_check
  check (method in ('MANUAL', 'IPAYMU', 'OFFLINE'));

create index if not exists payment_transactions_method_idx
  on public.payment_transactions (method);

-- ---------------------------------------------------------------------------
-- 2. payment_initiate — tambahan parameter p_payer_alias (opsional).
--    Isi fungsi lain (validasi santri satu lembaga, multi bulan, kunci baris,
--    bayar di muka 11 bulan) TIDAK berubah dari V12.
-- ---------------------------------------------------------------------------
drop function if exists public.payment_initiate(jsonb, text);

create or replace function public.payment_initiate(
  p_items jsonb,                       -- [{studentId, y, m, amount}]
  p_method text,                       -- MANUAL | IPAYMU
  p_payer_alias text default null      -- "atas nama" (opsional)
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_item jsonb;
  v_student public.students;
  v_invoice public.payment_invoices;
  v_today record;
  v_default integer;
  v_cur integer;
  v_idx integer;
  v_sid uuid;
  v_y integer;
  v_m integer;
  v_amount integer;
  v_key text;
  v_alias text;
  v_seen text[] := '{}';
  v_invoice_ids uuid[] := '{}';
  v_amounts integer[] := '{}';
  v_total integer := 0;
  v_tx_id uuid;
  v_reference text;
  n integer;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' or v_profile.tenant_id is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if p_method not in ('MANUAL','IPAYMU') then raise exception 'METODE_TIDAK_VALID'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'ITEM_KOSONG';
  end if;
  if jsonb_array_length(p_items) > 120 then raise exception 'ITEM_TERLALU_BANYAK'; end if;

  v_alias := nullif(btrim(coalesce(p_payer_alias, '')), '');
  if v_alias is not null and char_length(v_alias) > 60 then raise exception 'NAMA_TERLALU_PANJANG'; end if;

  select * into v_today from public.jakarta_today();
  v_cur := v_today.y * 12 + v_today.m;
  select greatest(coalesce(default_amount, 1000), 1000) into v_default
  from public.platform_payment_settings where id;
  v_default := coalesce(v_default, 1000);

  -- Validasi seluruh item SEBELUM membuat transaksi (rule #37/#100).
  for v_item in select * from jsonb_array_elements(p_items) loop
    begin
      v_sid    := (v_item->>'studentId')::uuid;
      v_y      := (v_item->>'y')::integer;
      v_m      := (v_item->>'m')::integer;
      v_amount := (v_item->>'amount')::integer;
    exception when others then
      raise exception 'ITEM_TIDAK_VALID';
    end;
    if v_sid is null or v_y is null or v_m is null or v_amount is null then
      raise exception 'ITEM_TIDAK_VALID';
    end if;
    if v_m not between 1 and 12 or v_y not between 2020 and 2100 then
      raise exception 'ITEM_TIDAK_VALID';
    end if;
    if v_amount < 1000 then raise exception 'NOMINAL_MINIMAL'; end if;

    v_key := v_sid::text || ':' || v_y::text || ':' || v_m::text;
    if v_key = any (v_seen) then raise exception 'ITEM_GANDA'; end if;
    v_seen := v_seen || v_key;

    select * into v_student from public.students
      where id = v_sid and tenant_id = v_profile.tenant_id and status = 'ACTIVE';
    if v_student is null then raise exception 'SANTRI_TIDAK_DITEMUKAN'; end if;

    select * into v_invoice from public.payment_invoices
      where tenant_id = v_profile.tenant_id and student_id = v_sid
        and year = v_y and month = v_m
      for update;

    if v_invoice is null then
      v_idx := v_y * 12 + v_m;
      if v_idx < v_cur then raise exception 'TAGIHAN_TIDAK_DITEMUKAN'; end if;
      if v_idx > v_cur + 11 then raise exception 'BULAN_DI_LUAR_BATAS'; end if;

      insert into public.payment_invoices (tenant_id, student_id, academic_year, year, month, amount)
      values (
        v_profile.tenant_id, v_sid,
        case when v_m >= 7 then v_y::text || '/' || (v_y + 1)::text
             else (v_y - 1)::text || '/' || v_y::text end,
        v_y, v_m, v_default
      )
      on conflict (tenant_id, student_id, academic_year, year, month) do nothing;

      select * into v_invoice from public.payment_invoices
        where tenant_id = v_profile.tenant_id and student_id = v_sid
          and year = v_y and month = v_m
        for update;
      if v_invoice is null then raise exception 'TAGIHAN_TIDAK_DITEMUKAN'; end if;
    end if;

    if v_invoice.status = 'PAID' then raise exception 'SUDAH_LUNAS'; end if;
    if exists (
      select 1 from public.payment_allocations a
      join public.payment_transactions t on t.id = a.transaction_id
      where a.invoice_id = v_invoice.id and t.status in ('PENDING','WAITING_CONFIRM')
    ) then raise exception 'MENUNGGU_PEMBAYARAN'; end if;
    if v_amount < v_invoice.amount then raise exception 'NOMINAL_KURANG'; end if;

    v_invoice_ids := v_invoice_ids || v_invoice.id;
    v_amounts     := v_amounts || v_amount;
    v_total       := v_total + v_amount;
  end loop;

  if p_method = 'IPAYMU' and v_total < 10000 then
    raise exception 'OTOMATIS_MINIMAL';
  end if;

  v_reference := 'INF-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));

  insert into public.payment_transactions (
    tenant_id, payer_profile_id, payer_name, payer_alias, method, total_amount, status, reference
  ) values (
    v_profile.tenant_id, v_profile.id, v_profile.full_name, v_alias, p_method, v_total, 'PENDING', v_reference
  )
  returning id into v_tx_id;

  for n in 1 .. array_length(v_invoice_ids, 1) loop
    insert into public.payment_allocations (transaction_id, invoice_id, tenant_id, amount)
    values (v_tx_id, v_invoice_ids[n], v_profile.tenant_id, v_amounts[n]);

    update public.payment_invoices set status = 'PENDING', updated_at = now()
    where id = v_invoice_ids[n] and status <> 'PAID';
  end loop;

  return jsonb_build_object(
    'transaction_id', v_tx_id, 'reference', v_reference,
    'total', v_total, 'items', array_length(v_invoice_ids, 1)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. payment_dev_arrears — daftar santri menunggak SEMUA lembaga,
--    diurutkan dari tunggakan paling lama (untuk layar pelunasan Developer).
-- ---------------------------------------------------------------------------
create or replace function public.payment_dev_arrears(
  p_query     text default null,
  p_tenant_id uuid default null,
  p_limit     integer default 200
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_today record;
  v_cur integer;
  v_limit integer;
  v_q text;
  v_default integer;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'DEVELOPER' then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_today from public.jakarta_today();
  v_cur   := v_today.y * 12 + v_today.m;
  v_limit := least(greatest(coalesce(p_limit, 200), 1), 500);
  v_q     := nullif(btrim(coalesce(p_query, '')), '');
  select greatest(coalesce(default_amount, 1000), 1000) into v_default
  from public.platform_payment_settings where id;

  return jsonb_build_object(
    'y', v_today.y, 'm', v_today.m,
    'defaultAmount', coalesce(v_default, 1000),
    'tenants', (
      select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'code', t.business_code)
                      order by t.name), '[]'::jsonb)
      from public.tenants t where t.status = 'ACTIVE'
    ),
    'students', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'studentId', q.id, 'name', q.name, 'code', q.code,
               'tenantId', q.tenant_id, 'tenantName', q.tenant_name, 'tenantCode', q.tenant_code,
               'oldestY', (q.oldest_idx - 1) / 12, 'oldestM', ((q.oldest_idx - 1) % 12) + 1,
               'monthsBehind', greatest(v_cur - q.oldest_idx, 0),
               'unpaidCount', q.cnt, 'unpaidTotal', q.total, 'invoices', q.invs
             ) order by q.oldest_idx, q.cnt desc, q.name), '[]'::jsonb)
      from (
        select s.id, s.full_name as name, s.business_code as code,
               t.id as tenant_id, t.name as tenant_name, t.business_code as tenant_code,
               min(i.year * 12 + i.month) filter (where i.status = 'UNPAID') as oldest_idx,
               count(*) filter (where i.status = 'UNPAID') as cnt,
               coalesce(sum(i.amount) filter (where i.status = 'UNPAID'), 0) as total,
               jsonb_agg(jsonb_build_object(
                 'id', i.id, 'y', i.year, 'm', i.month, 'amount', i.amount, 'status', i.status
               ) order by i.year, i.month) as invs
        from public.students s
        join public.tenants t on t.id = s.tenant_id and t.status = 'ACTIVE'
        join public.payment_invoices i on i.student_id = s.id
        where s.status = 'ACTIVE'
          and i.status <> 'PAID'
          and i.year * 12 + i.month <= v_cur
          and (p_tenant_id is null or s.tenant_id = p_tenant_id)
          and (v_q is null
               or s.full_name ilike '%' || v_q || '%'
               or s.business_code ilike '%' || v_q || '%'
               or t.name ilike '%' || v_q || '%'
               or t.business_code ilike '%' || v_q || '%')
        group by s.id, s.full_name, s.business_code, t.id, t.name, t.business_code
        having count(*) filter (where i.status = 'UNPAID') > 0
        order by min(i.year * 12 + i.month) filter (where i.status = 'UNPAID'),
                 count(*) filter (where i.status = 'UNPAID') desc, s.full_name
        limit v_limit
      ) q
    )
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. payment_dev_settle — DEVELOPER melunasi tagihan & menuliskan pembayarnya.
--    p_items       : [{studentId, y, m, amount}] (amount opsional -> nilai tagihan)
--    p_payer_name  : WAJIB — "dibayarkan oleh siapa" (tampil ke santri)
--    p_note        : catatan pelunasan (opsional, terlihat di detail transaksi)
--    p_force       : bila true, transaksi wali yang masih PENDING/menunggu
--                    konfirmasi untuk tagihan yang sama dibatalkan otomatis.
--    Satu transaksi dibuat PER LEMBAGA, langsung berstatus PAID.
-- ---------------------------------------------------------------------------
create or replace function public.payment_dev_settle(
  p_items      jsonb,
  p_payer_name text,
  p_note       text default null,
  p_force      boolean default false
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_item jsonb;
  v_student public.students;
  v_invoice public.payment_invoices;
  v_today record;
  v_default integer;
  v_cur integer;
  v_idx integer;
  v_sid uuid;
  v_y integer;
  v_m integer;
  v_amount integer;
  v_key text;
  v_name text;
  v_note text;
  v_seen text[] := '{}';
  v_tenants uuid[] := '{}';
  v_student_ids uuid[] := '{}';
  v_inv_ids uuid[] := '{}';
  v_inv_tenants uuid[] := '{}';
  v_amounts integer[] := '{}';
  v_conflict uuid[] := '{}';
  v_total integer := 0;
  v_tx_count integer := 0;
  v_tenant uuid;
  v_tx_id uuid;
  v_tx_total integer;
  v_reference text;
  n integer;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'DEVELOPER' then raise exception 'AKSES_DITOLAK'; end if;

  v_name := nullif(btrim(coalesce(p_payer_name, '')), '');
  if v_name is null then raise exception 'NAMA_PEMBAYAR_WAJIB'; end if;
  if char_length(v_name) < 2 or char_length(v_name) > 120 then raise exception 'NAMA_PEMBAYAR_TIDAK_VALID'; end if;
  v_note := nullif(btrim(coalesce(p_note, '')), '');

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'ITEM_KOSONG';
  end if;
  if jsonb_array_length(p_items) > 300 then raise exception 'ITEM_TERLALU_BANYAK'; end if;

  select * into v_today from public.jakarta_today();
  v_cur := v_today.y * 12 + v_today.m;
  select greatest(coalesce(default_amount, 1000), 1000) into v_default
  from public.platform_payment_settings where id;
  v_default := coalesce(v_default, 1000);

  -- Validasi seluruh item SEBELUM ada perubahan status.
  for v_item in select * from jsonb_array_elements(p_items) loop
    begin
      v_sid    := (v_item->>'studentId')::uuid;
      v_y      := (v_item->>'y')::integer;
      v_m      := (v_item->>'m')::integer;
      v_amount := nullif(v_item->>'amount', '')::integer;
    exception when others then
      raise exception 'ITEM_TIDAK_VALID';
    end;
    if v_sid is null or v_y is null or v_m is null then raise exception 'ITEM_TIDAK_VALID'; end if;
    if v_m not between 1 and 12 or v_y not between 2020 and 2100 then raise exception 'ITEM_TIDAK_VALID'; end if;

    v_key := v_sid::text || ':' || v_y::text || ':' || v_m::text;
    if v_key = any (v_seen) then raise exception 'ITEM_GANDA'; end if;
    v_seen := v_seen || v_key;

    select * into v_student from public.students where id = v_sid and status = 'ACTIVE';
    if v_student is null then raise exception 'SANTRI_TIDAK_DITEMUKAN'; end if;

    select * into v_invoice from public.payment_invoices
      where tenant_id = v_student.tenant_id and student_id = v_sid and year = v_y and month = v_m
      for update;

    if v_invoice is null then
      -- Bulan berjalan s.d. 11 bulan ke depan boleh dibuatkan tagihannya.
      v_idx := v_y * 12 + v_m;
      if v_idx < v_cur then raise exception 'TAGIHAN_TIDAK_DITEMUKAN'; end if;
      if v_idx > v_cur + 11 then raise exception 'BULAN_DI_LUAR_BATAS'; end if;

      insert into public.payment_invoices (tenant_id, student_id, academic_year, year, month, amount)
      values (
        v_student.tenant_id, v_sid,
        case when v_m >= 7 then v_y::text || '/' || (v_y + 1)::text
             else (v_y - 1)::text || '/' || v_y::text end,
        v_y, v_m, v_default
      )
      on conflict (tenant_id, student_id, academic_year, year, month) do nothing;

      select * into v_invoice from public.payment_invoices
        where tenant_id = v_student.tenant_id and student_id = v_sid and year = v_y and month = v_m
        for update;
      if v_invoice is null then raise exception 'TAGIHAN_TIDAK_DITEMUKAN'; end if;
    end if;

    if v_invoice.status = 'PAID' then raise exception 'SUDAH_LUNAS'; end if;

    -- Transaksi wali yang masih berjalan untuk tagihan ini.
    if exists (
      select 1 from public.payment_allocations a
      join public.payment_transactions t on t.id = a.transaction_id
      where a.invoice_id = v_invoice.id and t.status in ('PENDING','WAITING_CONFIRM')
    ) then
      if not p_force then raise exception 'MENUNGGU_PEMBAYARAN'; end if;
      select coalesce(v_conflict, '{}') || coalesce(array_agg(distinct t.id), '{}') into v_conflict
      from public.payment_allocations a
      join public.payment_transactions t on t.id = a.transaction_id
      where a.invoice_id = v_invoice.id
        and t.status in ('PENDING','WAITING_CONFIRM')
        and not (t.id = any (coalesce(v_conflict, '{}')));
    end if;

    v_amount := greatest(coalesce(v_amount, v_invoice.amount), v_invoice.amount);
    if v_amount < 1000 then raise exception 'NOMINAL_MINIMAL'; end if;

    v_inv_ids     := v_inv_ids || v_invoice.id;
    v_inv_tenants := v_inv_tenants || v_student.tenant_id;
    v_amounts     := v_amounts || v_amount;
    v_total       := v_total + v_amount;
    if not (v_student.tenant_id = any (v_tenants)) then
      v_tenants := v_tenants || v_student.tenant_id;
    end if;
    if not (v_sid = any (v_student_ids)) then
      v_student_ids := v_student_ids || v_sid;
    end if;
  end loop;

  -- Batalkan transaksi wali yang bentrok (hanya bila p_force).
  if array_length(v_conflict, 1) is not null then
    update public.payment_transactions t
    set status = 'CANCELLED',
        reject_reason = 'Tagihan dilunasi langsung oleh pengelola platform (' || v_name || ').',
        updated_at = now()
    where t.id = any (v_conflict) and t.status in ('PENDING','WAITING_CONFIRM');

    insert into public.notifications (user_id, tenant_id, type, title, body, link)
    select t.payer_profile_id, t.tenant_id, 'PAYMENT_REJECTED',
           'Transaksi dibatalkan — tagihan sudah dilunasi',
           'Tagihan pada transaksi ' || t.reference || ' telah dilunasi oleh ' || v_name || '.',
           '/santri/infak'
    from public.payment_transactions t
    where t.id = any (v_conflict);
  end if;

  -- Satu transaksi PAID per lembaga.
  foreach v_tenant in array v_tenants loop
    v_tx_total := 0;
    for n in 1 .. array_length(v_inv_ids, 1) loop
      if v_inv_tenants[n] = v_tenant then v_tx_total := v_tx_total + v_amounts[n]; end if;
    end loop;
    if v_tx_total < 1000 then continue; end if;

    v_reference := 'INF-DEV-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

    insert into public.payment_transactions (
      tenant_id, payer_profile_id, payer_name, payer_alias, method, total_amount,
      status, reference, payer_note, submitted_at, confirmed_by, confirmed_at
    ) values (
      v_tenant, v_profile.id, v_profile.full_name, v_name, 'OFFLINE', v_tx_total,
      'PAID', v_reference, v_note, now(), v_profile.id, now()
    )
    returning id into v_tx_id;
    v_tx_count := v_tx_count + 1;

    for n in 1 .. array_length(v_inv_ids, 1) loop
      if v_inv_tenants[n] <> v_tenant then continue; end if;

      insert into public.payment_allocations (transaction_id, invoice_id, tenant_id, amount)
      values (v_tx_id, v_inv_ids[n], v_tenant, v_amounts[n])
      on conflict (transaction_id, invoice_id) do nothing;

      update public.payment_invoices
      set status = 'PAID', paid_at = now(), paid_via = 'OFFLINE', updated_at = now()
      where id = v_inv_ids[n];
    end loop;

    -- Kabari wali/santri yang tagihannya dilunasi.
    insert into public.notifications (user_id, tenant_id, type, title, body, link)
    select distinct g.profile_id, v_tenant, 'PAYMENT_CONFIRMED',
           'Infak Pengembangan telah dilunasi',
           'Infak Pengembangan ' || s.full_name || ' telah dibayarkan oleh ' || v_name || '.',
           '/santri/infak'
    from public.payment_allocations a
    join public.payment_invoices i on i.id = a.invoice_id
    join public.students s on s.id = i.student_id
    join public.guardian_students gs on gs.student_id = s.id
    join public.guardians g on g.id = gs.guardian_id
    where a.transaction_id = v_tx_id and g.profile_id is not null;
  end loop;

  return jsonb_build_object(
    'transactions', v_tx_count,
    'invoices', coalesce(array_length(v_inv_ids, 1), 0),
    'students', coalesce(array_length(v_student_ids, 1), 0),
    'total', v_total,
    'payerName', v_name,
    'cancelled', coalesce(array_length(v_conflict, 1), 0)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Tampilan ke santri memakai "atas nama" bila ada (payer_alias).
--    payment_wali_status & payment_wali_history — hanya bagian pembayar yang
--    berubah; struktur lain tetap sama dengan V12.
-- ---------------------------------------------------------------------------
create or replace function public.payment_wali_status(p_year integer default null, p_month integer default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_guardian public.guardians;
  v_today record;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' then raise exception 'AKSES_DITOLAK'; end if;
  select * into v_today from public.jakarta_today();
  p_year := coalesce(p_year, v_today.y); p_month := coalesce(p_month, v_today.m);
  select * into v_guardian from public.guardians where profile_id = v_profile.id;

  return (select coalesce(jsonb_agg(jsonb_build_object(
    'studentId', s.id, 'name', s.full_name, 'code', s.business_code,
    'status', i.status, 'amount', i.amount,
    'hasInvoice', i.id is not null,
    'paidAt', case when i.status = 'PAID' then coalesce(pi.paid_on, i.paid_at) end,
    'paidByName', case when i.status = 'PAID' then pi.payer_name end,
    'paidBySelf', (i.status = 'PAID' and pi.payer_id is not null and pi.payer_id = auth.uid()
                   and pi.method <> 'OFFLINE'),
    'paidVia', case when i.status = 'PAID' then i.paid_via end,
    'bundleMonths', case when i.status = 'PAID' then pi.bundle end
  ) order by s.full_name), '[]'::jsonb)
  from public.guardian_students gs
  join public.students s on s.id = gs.student_id and s.status = 'ACTIVE'
  left join public.payment_invoices i
    on i.student_id = s.id and i.year = p_year and i.month = p_month
  left join lateral (
    select coalesce(t.submitted_at, t.confirmed_at) as paid_on,
           coalesce(nullif(btrim(coalesce(t.payer_alias, '')), ''), t.payer_name) as payer_name,
           t.payer_profile_id as payer_id, t.method,
           (select count(*) from public.payment_allocations a2
              join public.payment_invoices i2 on i2.id = a2.invoice_id
             where a2.transaction_id = t.id and i2.student_id = i.student_id)::int as bundle
    from public.payment_allocations a
    join public.payment_transactions t on t.id = a.transaction_id and t.status = 'PAID'
    where a.invoice_id = i.id
    order by t.confirmed_at desc nulls last
    limit 1
  ) pi on i.status = 'PAID'
  where v_guardian is not null and gs.guardian_id = v_guardian.id);
end;
$$;

create or replace function public.payment_wali_history(p_limit integer default 12)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_guardian public.guardians;
  v_today record;
  v_cur integer;
  v_limit integer;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' then raise exception 'AKSES_DITOLAK'; end if;
  select * into v_today from public.jakarta_today();
  v_cur := v_today.y * 12 + v_today.m;
  v_limit := least(greatest(coalesce(p_limit, 12), 1), 36);
  select * into v_guardian from public.guardians where profile_id = v_profile.id;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'studentId', s.id, 'name', s.full_name, 'code', s.business_code,
      'items', (
        select coalesce(jsonb_agg(z.j order by z.idx desc), '[]'::jsonb)
        from (
          select i.year * 12 + i.month as idx,
            jsonb_build_object(
              'id', i.id, 'y', i.year, 'm', i.month, 'status', i.status,
              'amount', case when i.status = 'PAID' then coalesce(pi.paid_amount, i.amount) else i.amount end,
              'paidAt', case when i.status = 'PAID' then coalesce(pi.paid_on, i.paid_at) end,
              'paidByName', case when i.status = 'PAID' then pi.payer_name end,
              'paidBySelf', (i.status = 'PAID' and pi.payer_id is not null and pi.payer_id = auth.uid()
                             and pi.method <> 'OFFLINE'),
              'paidVia', case when i.status = 'PAID' then i.paid_via end,
              'reference', case when i.status = 'PAID' then pi.reference end,
              'bundleMonths', case when i.status = 'PAID' then pi.bundle end,
              'paidInAdvance', case
                 when i.status = 'PAID' and coalesce(pi.paid_on, i.paid_at) is not null
                   then (coalesce(pi.paid_on, i.paid_at) at time zone 'Asia/Jakarta')::date < make_date(i.year, i.month, 1)
                 else false end
            ) as j
          from public.payment_invoices i
          left join lateral (
            select coalesce(t.submitted_at, t.confirmed_at) as paid_on,
                   coalesce(nullif(btrim(coalesce(t.payer_alias, '')), ''), t.payer_name) as payer_name,
                   t.payer_profile_id as payer_id, t.reference, t.method,
                   a.amount as paid_amount,
                   (select count(*) from public.payment_allocations a2
                      join public.payment_invoices i2 on i2.id = a2.invoice_id
                     where a2.transaction_id = t.id and i2.student_id = i.student_id)::int as bundle
            from public.payment_allocations a
            join public.payment_transactions t on t.id = a.transaction_id and t.status = 'PAID'
            where a.invoice_id = i.id
            order by t.confirmed_at desc nulls last
            limit 1
          ) pi on i.status = 'PAID'
          where i.student_id = s.id
            and (i.status = 'PAID' or i.year * 12 + i.month <= v_cur)
          order by i.year desc, i.month desc
          limit v_limit
        ) z
      )
    ) order by s.full_name), '[]'::jsonb)
    from public.guardian_students gs
    join public.students s on s.id = gs.student_id and s.status = 'ACTIVE'
    where v_guardian is not null and gs.guardian_id = v_guardian.id
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Detail transaksi Developer: tampilkan "atas nama" + catatan pelunasan.
-- ---------------------------------------------------------------------------
create or replace function public.payment_dev_detail(p_transaction_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_tx public.payment_transactions;
  v_tenant public.tenants;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'DEVELOPER' then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_tx from public.payment_transactions where id = p_transaction_id;
  if v_tx is null then raise exception 'TRANSAKSI_TIDAK_DITEMUKAN'; end if;
  select * into v_tenant from public.tenants where id = v_tx.tenant_id;

  return jsonb_build_object(
    'id', v_tx.id, 'reference', v_tx.reference, 'payerName', v_tx.payer_name,
    'payerAlias', nullif(btrim(coalesce(v_tx.payer_alias, '')), ''),
    'tenantName', v_tenant.name, 'tenantCode', v_tenant.business_code,
    'method', v_tx.method, 'status', v_tx.status, 'total', v_tx.total_amount,
    'proofPath', v_tx.proof_path, 'payerNote', v_tx.payer_note,
    'rejectReason', v_tx.reject_reason, 'providerTrxId', v_tx.provider_trx_id,
    'providerPaidVia', v_tx.provider_paid_via,
    'createdAt', v_tx.created_at, 'confirmedAt', v_tx.confirmed_at,
    'allocations', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'student', s.full_name, 'code', s.business_code,
               'y', i.year, 'm', i.month, 'amount', a.amount, 'invoiceStatus', i.status
             ) order by s.full_name, i.year, i.month), '[]'::jsonb)
      from public.payment_allocations a
      join public.payment_invoices i on i.id = a.invoice_id
      join public.students s on s.id = i.student_id
      where a.transaction_id = v_tx.id
    )
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Hak akses
-- ---------------------------------------------------------------------------
grant execute on function
  public.payment_initiate(jsonb, text, text),
  public.payment_dev_arrears(text, uuid, integer),
  public.payment_dev_settle(jsonb, text, text, boolean),
  public.payment_wali_status(integer, integer),
  public.payment_wali_history(integer),
  public.payment_dev_detail(uuid)
to authenticated;
-- ============================================================================
-- SOURCE: 20260922090000_tahfizh_v28_rapat_urutan_nis.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V28 — TAMPILAN RAPAT + URUTAN NIS
-- ============================================================================
-- 1. Presensi guru: daftar santri per halaqah diurut berdasarkan NIS
--    (business_code), bukan abjad nama. Kolom NIS ditambahkan di UI (lihat
--    perubahan attendance-sheet.tsx).
-- 2. Menu Tahfidz guru: kolom "Kelas" & "Jml" pada grid dihapus, kolom NIS
--    ditambahkan (business_code). Urutan baris = jumlah surat yang sudah
--    DINILAI (terbanyak dulu), bila sama maka NIS LEBIH BESAR tampil lebih
--    atas (dihitung & diurutkan di client agar sinkron dengan status sel
--    yang baru saja diubah guru — lihat grid-client.tsx).
-- 3. Hadits, Doa Harian, Tajwid, Tugas: daftar santri diurut berdasarkan NIS.
-- Tidak ada perubahan tabel/RLS; hanya definisi fungsi (idempoten).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. halaqah_detail — anggota halaqah (dipakai Presensi) diurut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.halaqah_detail(p_halaqah_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_teacher uuid := public.halaqah_current_teacher();
  v_role text;
  v_row public.halaqahs;
begin
  select role::text into v_role from public.profiles where id = auth.uid();
  if v_tenant is null then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_row from public.halaqahs
  where id = p_halaqah_id and tenant_id = v_tenant;
  if v_row is null then raise exception 'HALAQAH_TIDAK_DITEMUKAN'; end if;

  if v_role = 'USTADZ' and not public.halaqah_teacher_has_access(p_halaqah_id, v_teacher) then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('ADMIN', 'KOORDINATOR', 'DEVELOPER', 'USTADZ') then
    raise exception 'AKSES_DITOLAK';
  end if;

  return jsonb_build_object(
    'halaqah', to_jsonb(v_row),
    'teachers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.full_name, 'code', t.business_code,
        'isPrimary', ht.is_primary)
        order by ht.is_primary desc, t.full_name)
      from public.halaqah_teachers ht
      join public.teachers t on t.id = ht.teacher_id
      where ht.halaqah_id = p_halaqah_id
    ), '[]'::jsonb),
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.full_name, 'code', s.business_code, 'gender', s.gender)
        -- V28: urut NIS (bukan abjad) agar konsisten dengan daftar induk santri.
        order by s.business_code, s.full_name)
      from public.halaqah_students hs
      join public.students s on s.id = hs.student_id
      where hs.halaqah_id = p_halaqah_id and hs.left_at is null
    ), '[]'::jsonb),
    'studentCount', (select count(*) from public.halaqah_students hs
                     where hs.halaqah_id = p_halaqah_id and hs.left_at is null),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'studentName', s2.full_name, 'halaqahName', h2.name,
        'joinedAt', hs2.joined_at, 'leftAt', hs2.left_at)
        order by hs2.joined_at desc)
      from public.halaqah_students hs2
      join public.students s2 on s2.id = hs2.student_id
      join public.halaqahs h2 on h2.id = hs2.halaqah_id
      where hs2.student_id in (
        select student_id from public.halaqah_students where halaqah_id = p_halaqah_id
      )
    ), '[]'::jsonb)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. tahfidz_surahs_grid — tambahkan `code` (NIS). `kelas` tetap dikirim
--    untuk kompatibilitas (tidak lagi dipakai di grid guru, hanya dasbor
--    santri via tahfidz_santri_grid yang terpisah).
-- ---------------------------------------------------------------------------
create or replace function public.tahfidz_surahs_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_students jsonb;
  v_rows    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    select t.id into v_teacher
    from public.teachers t
    where t.tenant_id = v_tenant::uuid
      and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
    order by t.created_at desc
    limit 1;
    if v_teacher is null then
      return jsonb_build_object('students', '[]'::jsonb, 'rows', '[]'::jsonb);
    end if;
  end if;

  -- V28: kolom NIS ditambahkan; urutan dasar tetap nama (pengurutan akhir —
  -- jumlah hafalan lalu NIS terbesar di atas — dilakukan di client karena
  -- tergantung status sel yang sedang diedit guru).
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'name', s.full_name,
           'nickname', s.nickname,
           'code', s.business_code,
           'kelas', h.name
         ) order by lower(btrim(s.full_name))), '[]'::jsonb)
  into v_students
  from public.students s
  left join lateral (
    select hq.name
    from public.halaqah_students hs
    join public.halaqahs hq on hq.id = hs.halaqah_id
    where hs.student_id = s.id
      and hs.left_at is null
    order by hs.joined_at desc
    limit 1
  ) h on true
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'surahId', ts.id,
           'name', coalesce(ts.name_override, m.name),
           'sortOrder', ts.sort_order
         ) order by ts.sort_order), '[]'::jsonb)
  into v_rows
  from public.tahfidz_tenant_surahs ts
  left join public.tahfidz_surahs m on m.id = ts.surah_id
  where ts.tenant_id = v_tenant::uuid
    and ts.is_active = true;

  return jsonb_build_object('students', v_students, 'rows', v_rows);
end;
$$;

grant execute on function public.tahfidz_surahs_grid() to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Hadits & Doa Harian (learning_grid) — tambahkan `code` (NIS), urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.learning_grid(p_module text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_materials jsonb;
  v_students  jsonb;
  v_cells     jsonb;
  v_stable    text;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;
  if p_module not in ('HADITS', 'DOA') then
    raise exception 'MODUL_TIDAK_VALID';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.current_teacher_id();
    if v_teacher is null then
      select t.id into v_teacher
      from public.teachers t
      where t.tenant_id = v_tenant
        and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
      order by t.created_at desc
      limit 1;
    end if;
    if v_teacher is null then
      return jsonb_build_object('materials', '[]'::jsonb, 'students', '[]'::jsonb, 'cells', '[]'::jsonb);
    end if;
  end if;

  v_stable := case p_module when 'HADITS' then 'hadith_materials' else 'daily_prayer_materials' end;

  execute format(
    'select coalesce(jsonb_agg(jsonb_build_object(''materialId'', m.id, ''title'', m.title, ''sortOrder'', m.sort_order) order by m.sort_order), ''[]''::jsonb)
     from public.%I m
     where m.tenant_id = $1 and m.is_active',
    v_stable
  )
  using v_tenant
  into v_materials;

  -- V28: kolom NIS + urut NIS (bukan abjad).
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'name', s.full_name, 'nickname', s.nickname, 'code', s.business_code
         ) order by s.business_code, s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  with latest as (
    select distinct on (a.student_id, coalesce(a.hadith_id, a.prayer_id, a.tajwid_id))
      a.student_id,
      coalesce(a.hadith_id, a.prayer_id, a.tajwid_id) as material_id,
      a.status,
      a.score_label,
      a.score_value
    from public.learning_assessments a
    where a.tenant_id = v_tenant
      and a.module_type = p_module::public.learning_module
      and a.deleted_at is null
      and a.student_id in (select (x->>'id')::uuid from jsonb_array_elements(v_students) x)
    order by a.student_id, coalesce(a.hadith_id, a.prayer_id, a.tajwid_id), a.created_at desc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'materialId', l.material_id, 'studentId', l.student_id,
           'status', l.status, 'scoreLabel', l.score_label, 'scoreValue', l.score_value
         )), '[]'::jsonb)
  into v_cells
  from latest l;

  return jsonb_build_object('materials', v_materials, 'students', v_students, 'cells', v_cells);
end;
$$;

grant execute on function public.learning_grid(text) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Tajwid (tajwid_materi_grid) — tambahkan `code` (NIS), urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.tajwid_materi_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid      uuid := auth.uid();
  v_tenant   uuid;
  v_role     text;
  v_teacher  uuid;
  v_materi   jsonb;
  v_students jsonb;
  v_scores   jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null or v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.tajwid_teacher_for_session();
    if v_teacher is null then
      return jsonb_build_object('materi', '[]'::jsonb, 'students', '[]'::jsonb, 'scores', '[]'::jsonb);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', m.id,
           'title', m.title,
           'description', m.description
         ) order by m.created_at desc, m.id), '[]'::jsonb)
  into v_materi
  from public.tajwid_materi m
  where m.tenant_id = v_tenant::uuid
    and m.deleted_at is null;

  -- V28: kolom NIS + urut NIS (bukan abjad).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'name', s.full_name,
      'nickname', s.nickname,
      'code', s.business_code
    ) order by s.business_code, s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students hs on hs.halaqah_id = ht.halaqah_id and hs.left_at is null
      where ht.teacher_id = v_teacher and hs.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'materiId', sc.materi_id,
           'studentId', sc.student_id,
           'mode', sc.mode,
           'scoreValue', sc.score_value,
           'scoreLabel', sc.score_label
         )), '[]'::jsonb)
  into v_scores
  from public.tajwid_materi_scores sc
  join public.tajwid_materi m on m.id = sc.materi_id
  where sc.tenant_id = v_tenant::uuid
    and m.deleted_at is null
    and (v_role <> 'USTADZ' or sc.student_id in (
      select hs.student_id
      from public.halaqah_teachers ht
      join public.halaqah_students hs on hs.halaqah_id = ht.halaqah_id and hs.left_at is null
      where ht.teacher_id = v_teacher
    ));

  return jsonb_build_object('materi', v_materi, 'students', v_students, 'scores', v_scores);
end;
$$;

grant execute on function public.tajwid_materi_grid() to authenticated;

-- ---------------------------------------------------------------------------
-- 5. Tugas (tugas_halaqah_grid) — tambahkan `code` (NIS), urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.tugas_halaqah_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah jsonb;
  v_tasks   jsonb;
  v_students jsonb;
  v_scores  jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.tugas_teacher_for_session();
    if v_teacher is null then
      return jsonb_build_object('halaqah', '[]'::jsonb, 'tasks', '[]'::jsonb, 'students', '[]'::jsonb, 'scores', '[]'::jsonb);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'name', h.name) order by h.name), '[]'::jsonb)
  into v_halaqah
  from public.halaqahs h
  where h.tenant_id = v_tenant::uuid
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      where ht.halaqah_id = h.id and ht.teacher_id = v_teacher
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', th.id,
           'title', th.title,
           'description', th.description,
           'halaqahId', th.halaqah_id,
           'halaqahName', h.name,
           'assignedDate', th.assigned_date,
           'dueDate', th.due_date
         ) order by th.assigned_date desc, th.created_at desc), '[]'::jsonb)
  into v_tasks
  from public.tugas_halaqah th
  join public.halaqahs h on h.id = th.halaqah_id
  where th.tenant_id = v_tenant::uuid
    and th.deleted_at is null
    and (v_role <> 'USTADZ' or th.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    ));

  -- V28: kolom NIS + urut NIS (bukan abjad).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'name', s.full_name,
      'nickname', s.nickname,
      'code', s.business_code,
      'halaqahIds', coalesce((
        select jsonb_agg(hs.halaqah_id::text order by hs.halaqah_id)
        from public.halaqah_students hs
        where hs.student_id = s.id and hs.left_at is null
      ), '[]'::jsonb)
    ) order by s.business_code, s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'tugasId', sc.tugas_id,
           'studentId', sc.student_id,
           'mode', sc.mode,
           'scoreValue', sc.score_value,
           'scoreLabel', sc.score_label,
           'note', sc.note
         )), '[]'::jsonb)
  into v_scores
  from public.tugas_halaqah_scores sc
  join public.tugas_halaqah th on th.id = sc.tugas_id
  where sc.tenant_id = v_tenant::uuid
    and th.deleted_at is null
    and (v_role <> 'USTADZ' or th.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    ));

  return jsonb_build_object(
    'halaqah', v_halaqah,
    'tasks', v_tasks,
    'students', v_students,
    'scores', v_scores
  );
end;
$$;

grant execute on function public.tugas_halaqah_grid() to authenticated;
-- ============================================================================
-- SOURCE: 20260922100000_tahfizh_v29_infak_tidak_mampu.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V29 — INFAK PENGEMBANGAN: PENGAJUAN TIDAK MAMPU (KERINGANAN)
-- ============================================================================
-- Fitur baru di modul Infak Pengembangan:
--   1. Wali santri dapat mengajukan "tidak mampu" (keringanan infak) untuk
--      anaknya. Syarat: mengunggah Surat Keterangan Tidak Mampu yang
--      TERTANGGAL maksimal 7 hari terakhir (dan tidak bertanggal di masa depan).
--   2. Pengajuan masuk ke DEVELOPER. Developer memilih untuk MENGRATISKAN
--      infak santri tersebut dalam kurun waktu berapa bulan (1-24 bulan).
--   3. Bulan-bulan yang digratiskan otomatis bebas tagihan: tagihan yang sudah
--      ada (belum dibayar) ditandai lunas via WAIVER, dan tagihan bulan
--      berikutnya yang masuk periode keringanan langsung dibuat bebas.
--
-- Aman dijalankan ulang (idempoten). Tidak ada drop tabel / kolom / data.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Tabel pengajuan tidak mampu
-- ---------------------------------------------------------------------------
create table if not exists public.payment_waiver_requests (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants (id) on delete cascade,
  student_id       uuid not null references public.students (id) on delete cascade,
  guardian_id      uuid references public.guardians (id) on delete set null,
  requested_by     uuid references public.profiles (id) on delete set null,
  certificate_path text not null,                 -- bucket payment-proofs: {tenant}/waiver-….ext
  certificate_date date not null,                 -- tanggal surat (wajib ≤ 7 hari terakhir)
  reason           text,
  status           text not null default 'PENDING'
                   check (status in ('PENDING','APPROVED','REJECTED')),
  waive_months     integer check (waive_months is null or (waive_months between 1 and 24)),
  waive_from_year  integer,
  waive_from_month integer check (waive_from_month is null or (waive_from_month between 1 and 12)),
  decided_by       uuid references public.profiles (id) on delete set null,
  decided_at       timestamptz,
  reject_reason    text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index if not exists payment_waiver_requests_tenant_idx  on public.payment_waiver_requests (tenant_id);
create index if not exists payment_waiver_requests_student_idx on public.payment_waiver_requests (student_id);
create index if not exists payment_waiver_requests_status_idx  on public.payment_waiver_requests (status);

alter table public.payment_waiver_requests enable row level security;

-- Select: DEVELOPER melihat semua; wali hanya pengajuan miliknya sendiri.
-- Penulisan hanya lewat RPC SECURITY DEFINER (tanpa policy write untuk klien).
drop policy if exists payment_waiver_dev_select on public.payment_waiver_requests;
create policy payment_waiver_dev_select on public.payment_waiver_requests
  for select to authenticated
  using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'DEVELOPER'));

drop policy if exists payment_waiver_wali_select on public.payment_waiver_requests;
create policy payment_waiver_wali_select on public.payment_waiver_requests
  for select to authenticated
  using (requested_by = auth.uid());

comment on table public.payment_waiver_requests is
  'V29: pengajuan tidak mampu (keringanan infak) dari wali ke Developer, berisi surat keterangan & durasi bebas infak.';

-- ---------------------------------------------------------------------------
-- 2. Helper: apakah infak santri bebas pada bulan tertentu (pengajuan disetujui)
-- ---------------------------------------------------------------------------
create or replace function public.student_waived_at(
  p_student_id uuid,
  p_year       integer,
  p_month      integer
) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.payment_waiver_requests r
    where r.student_id = p_student_id
      and r.status = 'APPROVED'
      and r.waive_months is not null
      and (p_year * 12 + p_month) between
            (r.waive_from_year * 12 + r.waive_from_month)
            and (r.waive_from_year * 12 + r.waive_from_month + r.waive_months - 1)
  )
$$;

revoke all on function public.student_waived_at(uuid, integer, integer) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. invoice_generate_all — bulan dalam periode keringanan langsung bebas.
--    (Versi V26 + kesadaran keringanan; idempoten.)
-- ---------------------------------------------------------------------------
create or replace function public.invoice_generate_all(
  p_year  integer default null,
  p_month integer default null
)
returns integer language plpgsql security definer set search_path = public as $$
declare
  v_today record;
  v_amount integer;
  v_count integer := 0;
begin
  select * into v_today from public.jakarta_today();
  p_year  := coalesce(p_year, v_today.y);
  p_month := coalesce(p_month, v_today.m);

  select default_amount into v_amount from public.platform_payment_settings where id;
  v_amount := greatest(coalesce(v_amount, 1000), 1000);

  with ins as (
    insert into public.payment_invoices
      (tenant_id, student_id, academic_year, year, month, amount, status, paid_via, paid_at)
    select s.tenant_id, s.id,
           case when p_month >= 7 then p_year::text || '/' || (p_year + 1)::text
                else (p_year - 1)::text || '/' || p_year::text end,
           p_year, p_month, v_amount,
           case when w.waived then 'PAID'    else 'UNPAID' end,
           case when w.waived then 'WAIVER'  else null     end,
           case when w.waived then now()     else null     end
    from public.students s
    join public.tenants t on t.id = s.tenant_id and t.status = 'ACTIVE'
    cross join lateral (select public.student_waived_at(s.id, p_year, p_month) as waived) w
    where s.status = 'ACTIVE'
      and make_date(p_year, p_month, 1) >= public.tenant_billing_start_month(t.created_at)
      and not exists (
        select 1 from public.payment_invoices i
        where i.student_id = s.id and i.year = p_year and i.month = p_month
      )
    on conflict (tenant_id, student_id, academic_year, year, month) do nothing
    returning 1
  )
  select count(*) into v_count from ins;

  return v_count;
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. invoice_ensure_for_guardian — sama: bulan keringanan langsung bebas.
-- ---------------------------------------------------------------------------
create or replace function public.invoice_ensure_for_guardian(p_guardian_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_today record;
  v_amount integer;
begin
  select * into v_today from public.jakarta_today();
  select default_amount into v_amount from public.platform_payment_settings where id;
  v_amount := greatest(coalesce(v_amount, 1000), 1000);

  insert into public.payment_invoices
    (tenant_id, student_id, academic_year, year, month, amount, status, paid_via, paid_at)
  select s.tenant_id, s.id,
         case when v_today.m >= 7 then v_today.y::text || '/' || (v_today.y + 1)::text
              else (v_today.y - 1)::text || '/' || v_today.y::text end,
         v_today.y, v_today.m, v_amount,
         case when w.waived then 'PAID'   else 'UNPAID' end,
         case when w.waived then 'WAIVER' else null     end,
         case when w.waived then now()    else null     end
  from public.guardian_students gs
  join public.students s on s.id = gs.student_id and s.status = 'ACTIVE'
  join public.tenants t on t.id = s.tenant_id and t.status = 'ACTIVE'
  cross join lateral (select public.student_waived_at(s.id, v_today.y, v_today.m) as waived) w
  where gs.guardian_id = p_guardian_id
    and make_date(v_today.y, v_today.m, 1) >= public.tenant_billing_start_month(t.created_at)
    and not exists (
      select 1 from public.payment_invoices i
      where i.student_id = s.id and i.year = v_today.y and i.month = v_today.m
    )
  on conflict (tenant_id, student_id, academic_year, year, month) do nothing;
end;
$$;

revoke all on function public.invoice_generate_all(integer, integer) from public, anon, authenticated;
revoke all on function public.invoice_ensure_for_guardian(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. RPC — WALI mengajukan tidak mampu (surat keterangan ≤ 7 hari terakhir)
-- ---------------------------------------------------------------------------
create or replace function public.waiver_submit_request(
  p_student_id       uuid,
  p_certificate_path text,
  p_certificate_date date,
  p_reason           text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_profile  public.profiles;
  v_guardian public.guardians;
  v_student  public.students;
  v_today    date;
  v_id       uuid;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_guardian from public.guardians where profile_id = v_profile.id;
  if v_guardian is null then raise exception 'AKSES_DITOLAK'; end if;

  select s.* into v_student
  from public.students s
  join public.guardian_students gs on gs.student_id = s.id and gs.guardian_id = v_guardian.id
  where s.id = p_student_id;
  if v_student is null then raise exception 'SANTRI_TIDAK_DITEMUKAN'; end if;

  if btrim(coalesce(p_certificate_path, '')) = '' then raise exception 'SURAT_WAJIB'; end if;
  if p_certificate_date is null then raise exception 'TANGGAL_SURAT_WAJIB'; end if;

  v_today := (public.jakarta_now())::date;
  if p_certificate_date > v_today then raise exception 'TANGGAL_SURAT_MASA_DEPAN'; end if;
  if (v_today - p_certificate_date) > 7 then raise exception 'SURAT_KEDALUWARSA'; end if;

  if exists (
    select 1 from public.payment_waiver_requests r
    where r.student_id = p_student_id and r.status = 'PENDING'
  ) then
    raise exception 'SUDAH_DIAJUKAN';
  end if;

  insert into public.payment_waiver_requests
    (tenant_id, student_id, guardian_id, requested_by, certificate_path, certificate_date, reason)
  values (v_student.tenant_id, p_student_id, v_guardian.id, v_profile.id,
          btrim(p_certificate_path), p_certificate_date,
          nullif(btrim(coalesce(p_reason, '')), ''))
  returning id into v_id;

  -- Beri tahu seluruh Developer.
  insert into public.notifications (user_id, tenant_id, type, title, body, link)
  select p.id, null, 'INFO',
         'Pengajuan tidak mampu baru',
         v_profile.full_name || ' mengajukan keringanan infak untuk ' || v_student.full_name || '.',
         '/developer/infak/pengajuan'
  from public.profiles p
  where p.role = 'DEVELOPER';

  return v_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. RPC — daftar pengajuan wali & daftar pengajuan Developer
-- ---------------------------------------------------------------------------
create or replace function public.waiver_wali_list()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'WALI_SANTRI' then raise exception 'AKSES_DITOLAK'; end if;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id,
      'studentId', s.id, 'studentName', s.full_name, 'studentCode', s.business_code,
      'certificateDate', r.certificate_date,
      'reason', r.reason,
      'status', r.status,
      'months', r.waive_months,
      'fromYear', r.waive_from_year, 'fromMonth', r.waive_from_month,
      'decidedAt', r.decided_at,
      'rejectReason', r.reject_reason,
      'createdAt', r.created_at
    ) order by r.created_at desc), '[]'::jsonb)
    from public.payment_waiver_requests r
    join public.students s on s.id = r.student_id
    where r.requested_by = v_profile.id
  );
end;
$$;

create or replace function public.waiver_dev_list(
  p_status text default 'PENDING',
  p_query  text default null
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'DEVELOPER' then raise exception 'AKSES_DITOLAK'; end if;

  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id,
      'studentId', s.id, 'studentName', s.full_name, 'studentCode', s.business_code,
      'tenantName', t.name, 'tenantCode', t.business_code,
      'guardianName', gp.full_name,
      'requestedByName', p.full_name,
      'certificatePath', r.certificate_path,
      'certificateDate', r.certificate_date,
      'reason', r.reason,
      'status', r.status,
      'months', r.waive_months,
      'fromYear', r.waive_from_year, 'fromMonth', r.waive_from_month,
      'decidedAt', r.decided_at,
      'rejectReason', r.reject_reason,
      'createdAt', r.created_at
    ) order by r.created_at desc), '[]'::jsonb)
    from public.payment_waiver_requests r
    join public.students s on s.id = r.student_id
    join public.tenants t on t.id = r.tenant_id
    left join public.guardians g on g.id = r.guardian_id
    left join public.profiles gp on gp.id = g.profile_id
    left join public.profiles p on p.id = r.requested_by
    where (coalesce(p_status, 'ALL') = 'ALL' or r.status = p_status)
      and (
        p_query is null
        or s.full_name ilike '%' || p_query || '%'
        or s.business_code ilike '%' || p_query || '%'
        or t.name ilike '%' || p_query || '%'
        or t.business_code ilike '%' || p_query || '%'
      )
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. RPC — DEVELOPER menyetujui (gratis N bulan) atau menolak pengajuan
-- ---------------------------------------------------------------------------
create or replace function public.waiver_dev_decide(
  p_request_id uuid,
  p_decision   text,          -- APPROVE | REJECT
  p_months     integer default null,
  p_reason     text default null
)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_profile public.profiles;
  v_req     public.payment_waiver_requests;
  v_today   record;
  v_from    integer;
  v_until   integer;
begin
  select * into v_profile from public.profiles where id = auth.uid();
  if v_profile is null or v_profile.role <> 'DEVELOPER' then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_req from public.payment_waiver_requests where id = p_request_id for update;
  if v_req is null then raise exception 'PENGAJUAN_TIDAK_DITEMUKAN'; end if;
  if v_req.status <> 'PENDING' then raise exception 'STATUS_TIDAK_DAPAT_DIUBAH'; end if;

  select * into v_today from public.jakarta_today();

  if p_decision = 'APPROVE' then
    if p_months is null or p_months < 1 or p_months > 24 then raise exception 'DURASI_TIDAK_VALID'; end if;
    v_from  := v_today.y * 12 + v_today.m;
    v_until := v_from + p_months - 1;

    update public.payment_waiver_requests
    set status = 'APPROVED',
        waive_months = p_months,
        waive_from_year = v_today.y,
        waive_from_month = v_today.m,
        decided_by = auth.uid(), decided_at = now(), reject_reason = null, updated_at = now()
    where id = p_request_id;

    -- Bebaskan tagihan bulan berjalan & bulan berikutnya yang sudah terbit.
    update public.payment_invoices i
    set status = 'PAID', paid_via = 'WAIVER', paid_at = coalesce(i.paid_at, now()), updated_at = now()
    where i.student_id = v_req.student_id
      and i.status in ('UNPAID', 'PENDING')
      and (i.year * 12 + i.month) between v_from and v_until;

    if v_req.requested_by is not null then
      insert into public.notifications (user_id, tenant_id, type, title, body, link)
      values (v_req.requested_by, v_req.tenant_id, 'INFO',
              'Pengajuan tidak mampu disetujui',
              'Alhamdulillah, infak pengembangan digratiskan selama ' || p_months || ' bulan.',
              '/santri/infak');
    end if;
  elsif p_decision = 'REJECT' then
    update public.payment_waiver_requests
    set status = 'REJECTED',
        reject_reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Pengajuan tidak dapat disetujui.'),
        decided_by = auth.uid(), decided_at = now(), updated_at = now()
    where id = p_request_id;

    if v_req.requested_by is not null then
      insert into public.notifications (user_id, tenant_id, type, title, body, link)
      values (v_req.requested_by, v_req.tenant_id, 'INFO',
              'Pengajuan tidak mampu belum disetujui',
              coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Pengajuan tidak dapat disetujui.'),
              '/santri/infak');
    end if;
  else
    raise exception 'KEPUTUSAN_TIDAK_VALID';
  end if;
end;
$$;

grant execute on function
  public.waiver_submit_request(uuid, text, date, text),
  public.waiver_wali_list(),
  public.waiver_dev_list(text, text),
  public.waiver_dev_decide(uuid, text, integer, text)
to authenticated;

-- ---------------------------------------------------------------------------
-- 8. Storage — wali dapat membaca surat keterangan miliknya sendiri.
--    (Upload memakai policy "payment proofs insert member" yang sudah ada;
--     Developer membaca semua lewat policy "payment proofs read developer".)
-- ---------------------------------------------------------------------------
drop policy if exists "payment proofs read own waiver" on storage.objects;
create policy "payment proofs read own waiver"
  on storage.objects for select to authenticated
  using (
    bucket_id = 'payment-proofs'
    and exists (
      select 1 from public.payment_waiver_requests r
      where r.certificate_path = name and r.requested_by = auth.uid()
    )
  );
-- ============================================================================
-- SOURCE: 20260922150000_tahfizh_v30_nis_lembaga_grid_guru.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V30 — NIS LEMBAGA PADA GRID GURU (BUKAN NOMOR ID WEB)
-- ============================================================================
-- Perbaikan atas V28: kolom "NIS" pada menu guru (Presensi, Tahfidz, Hadits,
-- Doa Harian, Tajwid, Tugas) sebelumnya mengisi `code` dengan
-- students.business_code — yaitu nomor ID web berawalan "S-" yang dibuat
-- otomatis. Yang dimaksud NIS adalah Nomor Induk Santri/Sekolah yang
-- DIMASUKKAN LEMBAGA SENDIRI (students.nis, modul manajemen santri V12.1).
--
-- Perubahan (hanya definisi fungsi, idempoten):
--   1. halaqah_detail        — anggota halaqah untuk Presensi: `code` = nis,
--                              urut NIS (kosong paling bawah).
--   2. tahfidz_surahs_grid   — `code` = nis (urutan akhir tetap diurut client).
--   3. learning_grid         — Hadits & Doa Harian: `code` = nis, urut NIS.
--   4. tajwid_materi_grid    — Tajwid: `code` = nis, urut NIS.
--   5. tugas_halaqah_grid    — Tugas: `code` = nis, urut NIS.
--
-- Urutan "NIS" memakai (panjang teks, teks) agar NIS angka terurut alami
-- (9 sebelum 10); santri yang belum memiliki NIS diletakkan paling bawah.
-- Tidak ada perubahan tabel/RLS/data.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. halaqah_detail — anggota halaqah (dipakai Presensi) tampil & urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.halaqah_detail(p_halaqah_id uuid)
returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_teacher uuid := public.halaqah_current_teacher();
  v_role text;
  v_row public.halaqahs;
begin
  select role::text into v_role from public.profiles where id = auth.uid();
  if v_tenant is null then raise exception 'AKSES_DITOLAK'; end if;

  select * into v_row from public.halaqahs
  where id = p_halaqah_id and tenant_id = v_tenant;
  if v_row is null then raise exception 'HALAQAH_TIDAK_DITEMUKAN'; end if;

  if v_role = 'USTADZ' and not public.halaqah_teacher_has_access(p_halaqah_id, v_teacher) then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('ADMIN', 'KOORDINATOR', 'DEVELOPER', 'USTADZ') then
    raise exception 'AKSES_DITOLAK';
  end if;

  return jsonb_build_object(
    'halaqah', to_jsonb(v_row),
    'teachers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', t.id, 'name', t.full_name, 'code', t.business_code,
        'isPrimary', ht.is_primary)
        order by ht.is_primary desc, t.full_name)
      from public.halaqah_teachers ht
      join public.teachers t on t.id = ht.teacher_id
      where ht.halaqah_id = p_halaqah_id
    ), '[]'::jsonb),
    'students', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.full_name, 'code', nullif(btrim(s.nis), ''), 'gender', s.gender)
        -- V30: urut NIS lembaga (bukan abjad, bukan nomor ID web);
        -- NIS angka terurut alami (panjang dulu), tanpa NIS paling bawah.
        order by
          (nullif(btrim(s.nis), '') is null),
          char_length(nullif(btrim(s.nis), '')),
          nullif(btrim(s.nis), ''),
          s.full_name)
      from public.halaqah_students hs
      join public.students s on s.id = hs.student_id
      where hs.halaqah_id = p_halaqah_id and hs.left_at is null
    ), '[]'::jsonb),
    'studentCount', (select count(*) from public.halaqah_students hs
                     where hs.halaqah_id = p_halaqah_id and hs.left_at is null),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'studentName', s2.full_name, 'halaqahName', h2.name,
        'joinedAt', hs2.joined_at, 'leftAt', hs2.left_at)
        order by hs2.joined_at desc)
      from public.halaqah_students hs2
      join public.students s2 on s2.id = hs2.student_id
      join public.halaqahs h2 on h2.id = hs2.halaqah_id
      where hs2.student_id in (
        select student_id from public.halaqah_students where halaqah_id = p_halaqah_id
      )
    ), '[]'::jsonb)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. tahfidz_surahs_grid — `code` = NIS lembaga (urutan akhir tetap diurut
--    client: jumlah hafalan terbanyak dulu, lalu NIS terbesar di atas).
-- ---------------------------------------------------------------------------
create or replace function public.tahfidz_surahs_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_students jsonb;
  v_rows    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    select t.id into v_teacher
    from public.teachers t
    where t.tenant_id = v_tenant::uuid
      and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
    order by t.created_at desc
    limit 1;
    if v_teacher is null then
      return jsonb_build_object('students', '[]'::jsonb, 'rows', '[]'::jsonb);
    end if;
  end if;

  -- V30: kolom NIS = NIS lembaga (students.nis), bukan nomor ID web.
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'name', s.full_name,
           'nickname', s.nickname,
           'code', nullif(btrim(s.nis), ''),
           'kelas', h.name
         ) order by lower(btrim(s.full_name))), '[]'::jsonb)
  into v_students
  from public.students s
  left join lateral (
    select hq.name
    from public.halaqah_students hs
    join public.halaqahs hq on hq.id = hs.halaqah_id
    where hs.student_id = s.id
      and hs.left_at is null
    order by hs.joined_at desc
    limit 1
  ) h on true
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'surahId', ts.id,
           'name', coalesce(ts.name_override, m.name),
           'sortOrder', ts.sort_order
         ) order by ts.sort_order), '[]'::jsonb)
  into v_rows
  from public.tahfidz_tenant_surahs ts
  left join public.tahfidz_surahs m on m.id = ts.surah_id
  where ts.tenant_id = v_tenant::uuid
    and ts.is_active = true;

  return jsonb_build_object('students', v_students, 'rows', v_rows);
end;
$$;

grant execute on function public.tahfidz_surahs_grid() to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Hadits & Doa Harian (learning_grid) — `code` = NIS lembaga, urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.learning_grid(p_module text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_materials jsonb;
  v_students  jsonb;
  v_cells     jsonb;
  v_stable    text;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;
  if p_module not in ('HADITS', 'DOA') then
    raise exception 'MODUL_TIDAK_VALID';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.current_teacher_id();
    if v_teacher is null then
      select t.id into v_teacher
      from public.teachers t
      where t.tenant_id = v_tenant
        and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
      order by t.created_at desc
      limit 1;
    end if;
    if v_teacher is null then
      return jsonb_build_object('materials', '[]'::jsonb, 'students', '[]'::jsonb, 'cells', '[]'::jsonb);
    end if;
  end if;

  v_stable := case p_module when 'HADITS' then 'hadith_materials' else 'daily_prayer_materials' end;

  execute format(
    'select coalesce(jsonb_agg(jsonb_build_object(''materialId'', m.id, ''title'', m.title, ''sortOrder'', m.sort_order) order by m.sort_order), ''[]''::jsonb)
     from public.%I m
     where m.tenant_id = $1 and m.is_active',
    v_stable
  )
  using v_tenant
  into v_materials;

  -- V30: kolom NIS = NIS lembaga + urut NIS (bukan abjad / nomor ID web).
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'name', s.full_name, 'nickname', s.nickname, 'code', nullif(btrim(s.nis), '')
         ) order by
           (nullif(btrim(s.nis), '') is null),
           char_length(nullif(btrim(s.nis), '')),
           nullif(btrim(s.nis), ''),
           s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  with latest as (
    select distinct on (a.student_id, coalesce(a.hadith_id, a.prayer_id, a.tajwid_id))
      a.student_id,
      coalesce(a.hadith_id, a.prayer_id, a.tajwid_id) as material_id,
      a.status,
      a.score_label,
      a.score_value
    from public.learning_assessments a
    where a.tenant_id = v_tenant
      and a.module_type = p_module::public.learning_module
      and a.deleted_at is null
      and a.student_id in (select (x->>'id')::uuid from jsonb_array_elements(v_students) x)
    order by a.student_id, coalesce(a.hadith_id, a.prayer_id, a.tajwid_id), a.created_at desc
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'materialId', l.material_id, 'studentId', l.student_id,
           'status', l.status, 'scoreLabel', l.score_label, 'scoreValue', l.score_value
         )), '[]'::jsonb)
  into v_cells
  from latest l;

  return jsonb_build_object('materials', v_materials, 'students', v_students, 'cells', v_cells);
end;
$$;

grant execute on function public.learning_grid(text) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Tajwid (tajwid_materi_grid) — `code` = NIS lembaga, urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.tajwid_materi_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid      uuid := auth.uid();
  v_tenant   uuid;
  v_role     text;
  v_teacher  uuid;
  v_materi   jsonb;
  v_students jsonb;
  v_scores   jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null or v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.tajwid_teacher_for_session();
    if v_teacher is null then
      return jsonb_build_object('materi', '[]'::jsonb, 'students', '[]'::jsonb, 'scores', '[]'::jsonb);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', m.id,
           'title', m.title,
           'description', m.description
         ) order by m.created_at desc, m.id), '[]'::jsonb)
  into v_materi
  from public.tajwid_materi m
  where m.tenant_id = v_tenant::uuid
    and m.deleted_at is null;

  -- V30: kolom NIS = NIS lembaga + urut NIS (bukan abjad / nomor ID web).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'name', s.full_name,
      'nickname', s.nickname,
      'code', nullif(btrim(s.nis), '')
    ) order by
      (nullif(btrim(s.nis), '') is null),
      char_length(nullif(btrim(s.nis), '')),
      nullif(btrim(s.nis), ''),
      s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students hs on hs.halaqah_id = ht.halaqah_id and hs.left_at is null
      where ht.teacher_id = v_teacher and hs.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'materiId', sc.materi_id,
           'studentId', sc.student_id,
           'mode', sc.mode,
           'scoreValue', sc.score_value,
           'scoreLabel', sc.score_label
         )), '[]'::jsonb)
  into v_scores
  from public.tajwid_materi_scores sc
  join public.tajwid_materi m on m.id = sc.materi_id
  where sc.tenant_id = v_tenant::uuid
    and m.deleted_at is null
    and (v_role <> 'USTADZ' or sc.student_id in (
      select hs.student_id
      from public.halaqah_teachers ht
      join public.halaqah_students hs on hs.halaqah_id = ht.halaqah_id and hs.left_at is null
      where ht.teacher_id = v_teacher
    ));

  return jsonb_build_object('materi', v_materi, 'students', v_students, 'scores', v_scores);
end;
$$;

grant execute on function public.tajwid_materi_grid() to authenticated;

-- ---------------------------------------------------------------------------
-- 5. Tugas (tugas_halaqah_grid) — `code` = NIS lembaga, urut NIS.
-- ---------------------------------------------------------------------------
create or replace function public.tugas_halaqah_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_halaqah jsonb;
  v_tasks   jsonb;
  v_students jsonb;
  v_scores  jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.tugas_teacher_for_session();
    if v_teacher is null then
      return jsonb_build_object('halaqah', '[]'::jsonb, 'tasks', '[]'::jsonb, 'students', '[]'::jsonb, 'scores', '[]'::jsonb);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'name', h.name) order by h.name), '[]'::jsonb)
  into v_halaqah
  from public.halaqahs h
  where h.tenant_id = v_tenant::uuid
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      where ht.halaqah_id = h.id and ht.teacher_id = v_teacher
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', th.id,
           'title', th.title,
           'description', th.description,
           'halaqahId', th.halaqah_id,
           'halaqahName', h.name,
           'assignedDate', th.assigned_date,
           'dueDate', th.due_date
         ) order by th.assigned_date desc, th.created_at desc), '[]'::jsonb)
  into v_tasks
  from public.tugas_halaqah th
  join public.halaqahs h on h.id = th.halaqah_id
  where th.tenant_id = v_tenant::uuid
    and th.deleted_at is null
    and (v_role <> 'USTADZ' or th.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    ));

  -- V30: kolom NIS = NIS lembaga + urut NIS (bukan abjad / nomor ID web).
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'name', s.full_name,
      'nickname', s.nickname,
      'code', nullif(btrim(s.nis), ''),
      'halaqahIds', coalesce((
        select jsonb_agg(hs.halaqah_id::text order by hs.halaqah_id)
        from public.halaqah_students hs
        where hs.student_id = s.id and hs.left_at is null
      ), '[]'::jsonb)
    ) order by
      (nullif(btrim(s.nis), '') is null),
      char_length(nullif(btrim(s.nis), '')),
      nullif(btrim(s.nis), ''),
      s.full_name), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'tugasId', sc.tugas_id,
           'studentId', sc.student_id,
           'mode', sc.mode,
           'scoreValue', sc.score_value,
           'scoreLabel', sc.score_label,
           'note', sc.note
         )), '[]'::jsonb)
  into v_scores
  from public.tugas_halaqah_scores sc
  join public.tugas_halaqah th on th.id = sc.tugas_id
  where sc.tenant_id = v_tenant::uuid
    and th.deleted_at is null
    and (v_role <> 'USTADZ' or th.halaqah_id in (
      select ht.halaqah_id from public.halaqah_teachers ht where ht.teacher_id = v_teacher
    ));

  return jsonb_build_object(
    'halaqah', v_halaqah,
    'tasks', v_tasks,
    'students', v_students,
    'scores', v_scores
  );
end;
$$;

grant execute on function public.tugas_halaqah_grid() to authenticated;
-- ============================================================================
-- SOURCE: 20260923010000_tahfizh_v31_dashboard_quick_menu.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V31 — Menu Cepat (dashboard quick menu) per-user customization
--
-- Guru (dan role lain yang punya dashboard Menu Cepat) dapat mengatur urutan
-- serta menyembunyikan/menampilkan item Menu Cepat di halaman overview
-- masing-masing. Disimpan terpisah dari `menu_order` (yang mengatur urutan
-- sidebar) agar tidak saling mempengaruhi.
--
-- dashboard_quick_menu: jsonb array of keys (string), urutan sesuai preferensi
-- pengguna. Key yang TIDAK ada di array dianggap disembunyikan. NULL/kosong
-- = pakai urutan & tampilan default (semua item tampil, urutan bawaan).
-- ============================================================================

alter table public.profiles
  add column if not exists dashboard_quick_menu jsonb;
-- ============================================================================
-- SOURCE: 20260924010000_tahfizh_v32_bottom_nav_menu.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V32 — Menu Bawah (mobile bottom nav) per-user customization
--
-- Bar navigasi bawah khusus tampilan mobile (semua role), berisi maksimal 4
-- menu pilihan pengguna dari seluruh menu yang tersedia untuk role tersebut.
-- Disimpan terpisah dari `menu_order` (urutan sidebar) dan
-- `dashboard_quick_menu` (grid Menu Cepat) agar tidak saling memengaruhi.
--
-- bottom_nav_menu: jsonb array of keys (string), maksimal 4, urutan sesuai
-- preferensi pengguna. NULL/kosong = pakai 4 item default per role
-- (lihat BOTTOM_NAV_DEFAULT_KEYS di src/lib/terminology.ts).
-- ============================================================================

alter table public.profiles
  add column if not exists bottom_nav_menu jsonb;
-- ============================================================================
-- SOURCE: 20260924020000_tahfizh_v33_tahfidz_grid_teacher_id_fix.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V33 — PERBAIKAN: menu Tahfidz "Penilaian belum berhasil disimpan"
-- ============================================================================
-- Akar masalah: tahfidz_surahs_grid() / tahfidz_grid_cells() / tahfidz_save_grid()
-- (V12.6, migrasi 20260915220000) masih memakai PENCOCOKAN NAMA murni untuk
-- menemukan baris guru pemanggil:
--
--   where t.tenant_id = v_tenant
--     and lower(btrim(t.full_name)) = lower(btrim(<nama profil akun>))
--
-- Migrasi V12.11 (20260918020000) memperkenalkan public.current_teacher_id()
-- (link UUID teachers.profile_id → profiles.id, jauh lebih andal) dan
-- KOMENTARNYA sendiri menyatakan tahfidz_surahs_grid / tahfidz_save_grid ikut
-- diperbaiki — tapi CREATE OR REPLACE untuk ketiga fungsi tahfidz di atas
-- TIDAK PERNAH ditulis (hanya learning_grid/learning_save_grid yang benar-benar
-- diganti). Akibatnya: begitu nama di profil akun guru berbeda sedikit dari
-- teachers.full_name (gelar, spasi, nama diedit setelah akun dibuat, dsb.),
-- v_teacher = null → RPC melempar GURU_TIDAK_DITEMUKAN. Error ini tidak ada
-- di peta pesan saveTahfidzGridAction, jadi guru hanya melihat pesan generik
-- "Penilaian belum berhasil disimpan. Silakan coba lagi." walau input sudah
-- benar dan koneksi baik-baik saja.
--
-- Perbaikan (idempoten, tidak mengubah data): redefinisikan ketiga fungsi
-- dengan pola V12.11 yang sama seperti learning_grid — current_teacher_id()
-- dulu, fallback pencocokan nama lama bila baris guru belum ter-link.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. tahfidz_surahs_grid — grid penilaian guru (surat × santri binaan)
-- ---------------------------------------------------------------------------
create or replace function public.tahfidz_surahs_grid()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_students jsonb;
  v_rows    jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  -- V33: link UUID dulu (akurat walau nama profil ≠ nama guru), fallback nama.
  if v_role = 'USTADZ' then
    v_teacher := public.current_teacher_id();
    if v_teacher is null then
      select t.id into v_teacher
      from public.teachers t
      where t.tenant_id = v_tenant::uuid
        and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
      order by t.created_at desc
      limit 1;
    end if;
    if v_teacher is null then
      return jsonb_build_object('students', '[]'::jsonb, 'rows', '[]'::jsonb);
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id, 'name', s.full_name, 'nickname', s.nickname, 'code', s.business_code
         ) order by lower(btrim(s.full_name))), '[]'::jsonb)
  into v_students
  from public.students s
  where s.tenant_id = v_tenant::uuid
    and s.status = 'ACTIVE'
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = s.id
    ));

  select coalesce(jsonb_agg(jsonb_build_object(
           'surahId', ts.id,
           'name', coalesce(ts.name_override, m.name),
           'sortOrder', ts.sort_order
         ) order by ts.sort_order), '[]'::jsonb)
  into v_rows
  from public.tahfidz_tenant_surahs ts
  left join public.tahfidz_surahs m on m.id = ts.surah_id
  where ts.tenant_id = v_tenant::uuid
    and ts.is_active = true;

  return jsonb_build_object('students', v_students, 'rows', v_rows);
end;
$$;

grant execute on function public.tahfidz_surahs_grid() to authenticated;

-- ---------------------------------------------------------------------------
-- 2. tahfidz_grid_cells — nilai tersimpan per (surat, santri binaan)
-- ---------------------------------------------------------------------------
create or replace function public.tahfidz_grid_cells()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_uid     uuid := auth.uid();
  v_tenant  uuid;
  v_role    text;
  v_teacher uuid;
  v_cells   jsonb;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null then
    raise exception 'AKSES_DITOLAK';
  end if;
  if v_role not in ('USTADZ', 'KOORDINATOR', 'ADMIN') then
    raise exception 'AKSES_DITOLAK';
  end if;

  if v_role = 'USTADZ' then
    v_teacher := public.current_teacher_id();
    if v_teacher is null then
      select t.id into v_teacher
      from public.teachers t
      where t.tenant_id = v_tenant::uuid
        and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
      order by t.created_at desc
      limit 1;
    end if;
    if v_teacher is null then
      return '[]'::jsonb;
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'surahId', a.tenant_surah_id,
           'studentId', a.student_id,
           'status', a.status,
           'scoreLabel', a.score_label,
           'scoreValue', a.score_value
         )), '[]'::jsonb)
  into v_cells
  from public.tahfidz_assessments a
  where a.tenant_id = v_tenant::uuid
    and a.status in ('DIPELAJARI', 'DINILAI')
    and (v_role <> 'USTADZ' or exists (
      select 1 from public.halaqah_teachers ht
      join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
      where ht.teacher_id = v_teacher and h1.student_id = a.student_id
    ));

  return v_cells;
end;
$$;

grant execute on function public.tahfidz_grid_cells() to authenticated;

-- ---------------------------------------------------------------------------
-- 3. tahfidz_save_grid — simpan massal penilaian guru
-- ---------------------------------------------------------------------------
create or replace function public.tahfidz_save_grid(p_items jsonb)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid      uuid := auth.uid();
  v_tenant   uuid;
  v_role     text;
  v_teacher  uuid;
  v_item     jsonb;
  v_student  uuid;
  v_tsurah   uuid;
  v_mode     public.tahfidz_mode;
  v_status   text;
  v_score    numeric;
  v_label    text;
  v_note     text;
  v_saved    integer := 0;
  v_stenant  uuid;
  v_active   boolean;
  v_mode_db  public.tahfidz_mode;
  v_grade_ok boolean;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  -- V33: link UUID dulu (akurat walau nama profil ≠ nama guru), fallback nama.
  v_teacher := public.current_teacher_id();
  if v_teacher is null then
    select t.id into v_teacher
    from public.teachers t
    where t.tenant_id = v_tenant::uuid
      and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
    order by t.created_at desc
    limit 1;
  end if;
  if v_teacher is null then
    raise exception 'GURU_TIDAK_DITEMUKAN';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 2000 then
    raise exception 'BATCH_TIDAK_VALID';
  end if;

  select mode into v_mode_db from public.tahfidz_settings where tenant_id = v_tenant::uuid;
  v_mode_db := coalesce(v_mode_db, 'CENTANG');

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_student := nullif(v_item->>'studentId', '')::uuid;
    v_tsurah  := nullif(v_item->>'surahId', '')::uuid;
    v_mode    := coalesce(nullif(v_item->>'mode', ''), v_mode_db)::public.tahfidz_mode;
    v_status  := coalesce(v_item->>'status', 'DINILAI');
    v_score   := nullif(v_item->>'scoreValue', '')::numeric;
    v_label   := nullif(v_item->>'scoreLabel', '');
    v_note    := left(coalesce(v_item->>'note', ''), 500);

    if v_student is null or v_tsurah is null then
      raise exception 'BATCH_TIDAK_VALID';
    end if;
    if v_status not in ('BELUM', 'DIPELAJARI', 'DINILAI') then
      raise exception 'STATUS_TIDAK_VALID';
    end if;

    select s.tenant_id into v_stenant
    from public.students s
    where s.id = v_student
      and s.status = 'ACTIVE'
      and exists (
        select 1 from public.halaqah_teachers ht
        join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
        where ht.teacher_id = v_teacher and h1.student_id = s.id
      );
    if v_stenant is null or v_stenant <> v_tenant::uuid then
      raise exception 'SANTRI_BUKAN_BINAAN';
    end if;

    select ts.is_active into v_active
    from public.tahfidz_tenant_surahs ts
    where ts.id = v_tsurah and ts.tenant_id = v_tenant::uuid;
    if v_active is null then
      raise exception 'SURAT_TIDAK_AKTIF';
    end if;
    if v_active = false then
      raise exception 'SURAT_TIDAK_AKTIF';
    end if;

    if v_status = 'DINILAI' then
      if v_mode = 'CENTANG' then
        v_score := null;
        v_label := '✓';
      elsif v_mode = 'ANGKA' then
        if v_score is null or v_score < 1 or v_score > 100 or v_score <> floor(v_score) then
          raise exception 'NILAI_ANGKA_TIDAK_VALID';
        end if;
        v_label := null;
      else -- HURUF: wajib grade lembaga
        if v_label is null then
          raise exception 'GRADE_TIDAK_VALID';
        end if;
        select count(*) > 0 into v_grade_ok
        from public.tahfidz_grade_settings g
        where g.tenant_id = v_tenant::uuid and g.label = v_label;
        if not v_grade_ok then
          raise exception 'GRADE_TIDAK_VALID';
        end if;
        v_score := null;
      end if;
    else
      v_score := null;
      v_label := null;
    end if;

    insert into public.tahfidz_assessments
      (tenant_id, student_id, tenant_surah_id, teacher_id, assessed_by,
       status, score_value, score_label, note, mode_at_entry_cache)
    values
      (v_tenant::uuid, v_student, v_tsurah, v_teacher, v_uid,
       v_status::public.tahfidz_progress, v_score::int, v_label, nullif(v_note, ''), v_mode)
    on conflict (student_id, tenant_surah_id) do update
      set status            = excluded.status,
          score_value       = excluded.score_value,
          score_label       = excluded.score_label,
          note              = excluded.note,
          teacher_id        = excluded.teacher_id,
          assessed_by       = excluded.assessed_by,
          assessed_at       = now(),
          mode_at_entry_cache = excluded.mode_at_entry_cache,
          updated_at        = now();

    v_saved := v_saved + 1;
  end loop;

  return v_saved;
end;
$$;

grant execute on function public.tahfidz_save_grid(jsonb) to authenticated;
-- ============================================================================
-- SOURCE: 20260924030000_tahfizh_v34_tahfidz_save_grid_coalesce_fix.sql
-- ============================================================================
-- ============================================================================
-- TAHFIZH V34 — PERBAIKAN AKAR MASALAH SEBENARNYA: tahfidz_save_grid selalu
-- gagal (COALESCE types text and tahfidz_mode cannot be matched)
-- ============================================================================
-- V33 memperbaiki resolusi guru (current_teacher_id), tapi ITU BUKAN penyebab
-- utama "Penilaian belum berhasil disimpan". Penyebab sebenarnya: baris
--
--   v_mode := coalesce(nullif(v_item->>'mode', ''), v_mode_db)::public.tahfidz_mode;
--
-- mencoba COALESCE(text, tahfidz_mode) — dua tipe berbeda yang tidak bisa
-- digabungkan tanpa cast eksplisit. PostgreSQL TIDAK mendeteksi ini saat
-- CREATE OR REPLACE FUNCTION (ekspresi PL/pgSQL baru dicek tipe datanya saat
-- benar-benar dieksekusi), jadi migrasi selalu "berhasil" dijalankan di SQL
-- Editor, tapi tahfidz_save_grid GAGAL SETIAP KALI DIPANGGIL sejak awal
-- (V12.6) — untuk semua guru, terlepas dari status link profil/nama.
--
-- Perbaikan: cast sisi text ke enum SEBELUM di-COALESCE, bukan sesudahnya.
-- ============================================================================

create or replace function public.tahfidz_save_grid(p_items jsonb)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid      uuid := auth.uid();
  v_tenant   uuid;
  v_role     text;
  v_teacher  uuid;
  v_item     jsonb;
  v_student  uuid;
  v_tsurah   uuid;
  v_mode     public.tahfidz_mode;
  v_status   text;
  v_score    numeric;
  v_label    text;
  v_note     text;
  v_saved    integer := 0;
  v_stenant  uuid;
  v_active   boolean;
  v_mode_db  public.tahfidz_mode;
  v_grade_ok boolean;
begin
  if v_uid is null then
    raise exception 'AKSES_DITOLAK';
  end if;

  select tenant_id::text, role::text into v_tenant, v_role
  from public.profiles where id = v_uid;

  if v_tenant is null or v_role <> 'USTADZ' then
    raise exception 'AKSES_DITOLAK';
  end if;

  -- V33: link UUID dulu (akurat walau nama profil ≠ nama guru), fallback nama.
  v_teacher := public.current_teacher_id();
  if v_teacher is null then
    select t.id into v_teacher
    from public.teachers t
    where t.tenant_id = v_tenant::uuid
      and lower(btrim(t.full_name)) = lower(btrim((select full_name from public.profiles where id = v_uid)))
    order by t.created_at desc
    limit 1;
  end if;
  if v_teacher is null then
    raise exception 'GURU_TIDAK_DITEMUKAN';
  end if;

  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 2000 then
    raise exception 'BATCH_TIDAK_VALID';
  end if;

  select mode into v_mode_db from public.tahfidz_settings where tenant_id = v_tenant::uuid;
  v_mode_db := coalesce(v_mode_db, 'CENTANG');

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_student := nullif(v_item->>'studentId', '')::uuid;
    v_tsurah  := nullif(v_item->>'surahId', '')::uuid;
    -- V34: cast ke enum SEBELUM coalesce (bukan sesudah) — COALESCE(text, enum)
    -- tidak valid; COALESCE(enum, enum) valid.
    v_mode    := coalesce(nullif(v_item->>'mode', '')::public.tahfidz_mode, v_mode_db);
    v_status  := coalesce(v_item->>'status', 'DINILAI');
    v_score   := nullif(v_item->>'scoreValue', '')::numeric;
    v_label   := nullif(v_item->>'scoreLabel', '');
    v_note    := left(coalesce(v_item->>'note', ''), 500);

    if v_student is null or v_tsurah is null then
      raise exception 'BATCH_TIDAK_VALID';
    end if;
    if v_status not in ('BELUM', 'DIPELAJARI', 'DINILAI') then
      raise exception 'STATUS_TIDAK_VALID';
    end if;

    select s.tenant_id into v_stenant
    from public.students s
    where s.id = v_student
      and s.status = 'ACTIVE'
      and exists (
        select 1 from public.halaqah_teachers ht
        join public.halaqah_students h1 on h1.halaqah_id = ht.halaqah_id and h1.left_at is null
        where ht.teacher_id = v_teacher and h1.student_id = s.id
      );
    if v_stenant is null or v_stenant <> v_tenant::uuid then
      raise exception 'SANTRI_BUKAN_BINAAN';
    end if;

    select ts.is_active into v_active
    from public.tahfidz_tenant_surahs ts
    where ts.id = v_tsurah and ts.tenant_id = v_tenant::uuid;
    if v_active is null then
      raise exception 'SURAT_TIDAK_AKTIF';
    end if;
    if v_active = false then
      raise exception 'SURAT_TIDAK_AKTIF';
    end if;

    if v_status = 'DINILAI' then
      if v_mode = 'CENTANG' then
        v_score := null;
        v_label := '✓';
      elsif v_mode = 'ANGKA' then
        if v_score is null or v_score < 1 or v_score > 100 or v_score <> floor(v_score) then
          raise exception 'NILAI_ANGKA_TIDAK_VALID';
        end if;
        v_label := null;
      else -- HURUF: wajib grade lembaga
        if v_label is null then
          raise exception 'GRADE_TIDAK_VALID';
        end if;
        select count(*) > 0 into v_grade_ok
        from public.tahfidz_grade_settings g
        where g.tenant_id = v_tenant::uuid and g.label = v_label;
        if not v_grade_ok then
          raise exception 'GRADE_TIDAK_VALID';
        end if;
        v_score := null;
      end if;
    else
      v_score := null;
      v_label := null;
    end if;

    insert into public.tahfidz_assessments
      (tenant_id, student_id, tenant_surah_id, teacher_id, assessed_by,
       status, score_value, score_label, note, mode_at_entry_cache)
    values
      (v_tenant::uuid, v_student, v_tsurah, v_teacher, v_uid,
       v_status::public.tahfidz_progress, v_score::int, v_label, nullif(v_note, ''), v_mode)
    on conflict (student_id, tenant_surah_id) do update
      set status            = excluded.status,
          score_value       = excluded.score_value,
          score_label       = excluded.score_label,
          note              = excluded.note,
          teacher_id        = excluded.teacher_id,
          assessed_by       = excluded.assessed_by,
          assessed_at       = now(),
          mode_at_entry_cache = excluded.mode_at_entry_cache,
          updated_at        = now();

    v_saved := v_saved + 1;
  end loop;

  return v_saved;
end;
$$;

